pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space avoidance (fine-grained)
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 300.0;
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 30.0 + 42.0 * (1.0 - slack / cap);
            if slack < 1.0 {
                score -= 250.0;
            }
            if pr == ni {
                score -= 27.0;
            }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 13.0 * (after_next / cap);
            } else if after_next >= next_item_size.max(1) as f64 {
                score -= 9.0 + 4.0 * (after_next / cap);
            }
        } else {
            let gap = ni - pr;
            score += 9.0 * (pr / cap) + gap.min(60.0) * 1.5;
        }
    }

    // Dead-space ratio shaping conditioned on next item not fitting
    let dead = pr / cap;
    if dead > 0.0 && dead < 0.11 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 7.5 * (1.0 - dead / 0.11);
    } else if dead > 0.11 && dead < 0.24 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0 * (1.0 - (dead - 0.11) / 0.13);
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure
    let obp = open_bins_count as f64;
    score += (obp - 2.0).max(0.0) * 6.0;

    // Prefer tighter-than-mean bins
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Tightness reward
    let tight = 1.0 - dead;
    score -= 4.0 * tight * tight;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.4 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.55 {
            score -= base + 14.0 * (1.0 - 2.0 * progress);
        } else {
            score += base;
            score += 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.5;
        }
        if progress > 0.7 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let r = post_residual as f64;

    // Dead-space avoidance: tiny gaps are nearly useless, scaled harder.
    if post_residual > 0 {
        if r < 10.0 {
            score += 0.7 * (cap / 10.0 - r).max(0.0) + 30.0 * (10.0 - r);
        } else if r <= 25.0 {
            score += 1.0 * (25.0 - r);
        } else {
            score -= 0.25 * (r - 25.0);
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Tightness reward: filling most of the bin's space is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Lookahead synergy: strong reward when next item consumes the leftover,
    // weighted by next item size and closeness of fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.5 + 0.15 * (1.0 - slack / cap).min(1.0));
        if slack < 10.0 {
            score -= 12.0;
        }
    }
    // Penalize when next item cannot use a mid-sized leftover.
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: fewer new bins when crowded, relaxed late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).powf(1.3) * (1.0 - 0.5 * progress);
    score += 0.15 * pressure;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: costly unless crowded or next item is large.
    if bin_residual == bin_capacity {
        score += 25.0;
        score -= 0.35 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 0.25 * next_item_size as f64;
        }
        score -= 0.4 * fill_ratio * cap;
    }

    // Residual-balance term: prefer bins near the fleet mean, keeping gaps usable.
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 8.0 {
            score += 25.0 * (8.0 - r); // punish tiny dead gaps
        } else if r <= 20.0 {
            score += 0.6 * (20.0 - r); // small recoverable gaps
        } else {
            score -= 0.15 * (r - 20.0); // large flexible leftovers get mild bonus
        }
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Tightness reward: filling most of the bin's current space is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Lookahead: reward if next item fits the leftover (with decay on slack).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * 0.5;
        if slack < 12.0 {
            score -= 10.0; // near-perfect chain fit
        }
    }
    // Penalize if next item cannot use this leftover and leftover is mid-sized.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 35 {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure, relaxed late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.1 * (open_bins_count as f64).powf(1.2) * (1.0 - 0.5 * progress);

    // Last-chance bin: only bin that fits -> prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: cost of opening a fresh bin, offset by crowding
    // and by large next items needing fresh space.
    if bin_residual == bin_capacity {
        score += 20.0;
        score -= 0.4 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64;
        }
        score -= 0.3 * fill_ratio * bin_capacity as f64;
    }

    // Mild residual balancing toward the mean.
    score += 0.04 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.8 * progress * progress);
    score -= 0.6 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);

    // Reward leaving room for the next item, scaled by tightness of the fit
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) as f64;
            score -= ni * (0.5 + 0.15 * (1.0 - (slack / cap).min(1.0)));
            // Bonus if bin can host two more mid-size items
            if pr >= 2.0 * ni {
                score -= 2.0;
            }
        } else {
            // Penalize near-miss residuals that cannot host the next item
            score += 0.8 * ((ni - pr) / cap) + 0.3 * (ni - pr).min(50.0);
        }
    }

    // Penalize dead slivers unlikely to host typical items
    if pr > 0.0 && pr < cap / 10.0 {
        score += (cap / 10.0 - pr) * 0.7;
    }

    // Extra reward for near-perfect fills
    if pr > 0.0 && pr <= (item_size as f64) / 8.0 {
        score -= 1.0;
    }

    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(0.5);
        score += 1.5 + 1.5 * progress + 2.0 * pressure;
        // Allow a new bin if all open fits would leave bad slivers
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.5;
        }
    }

    // Mild tie-break toward bins with residual close to the running mean
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are nearly useless.
    if post_residual > 0 {
        let r = post_residual as f64;
        // "Unusable zone": gaps smaller than the smallest plausible item (1..100, so < 10 is dead).
        if r < 10.0 {
            score += 40.0 * (10.0 - r); // heavily punish tiny dead gaps
        } else if r <= 25.0 {
            // small-but-recoverable gaps: moderate penalty that decays as gap grows
            score += 1.2 * (25.0 - r);
        } else {
            // large leftovers are flexible: mild bonus relative to raw residual
            score -= 0.3 * (r - 25.0);
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Tightness reward: reward filling a large fraction of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage proliferating bins when many are open,
    // but relax pressure late in the stream (fewer future chances to close bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).powf(1.3) * (1.0 - 0.5 * progress);
    score += 0.15 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible, handled above).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item leaves a large, flexible gap AND current open bins are congested.
    if bin_residual == bin_capacity {
        score += 25.0; // baseline cost of a new bin
        score -= 0.35 * open_bins_count as f64; // but spreading load can pay off when crowded
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size > 0 {
            score -= 0.25 * next_item_size as f64;
        }
        // if the current item nearly fills the fresh bin, opening is fine
        score -= 0.4 * fill_ratio * bin_capacity as f64;
    }

    // Lookahead synergy: if next item fits exactly in this bin's post-residual,
    // reward this placement strongly (chains of complementary items).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 12.0; // next item will almost perfectly consume the leftover
        }
    }
    // penalize if next item cannot use this leftover at all and leftover is mid-sized
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 30 {
        score += 6.0;
    }

    // Mild preference for bins below mean residual (keeps residuals balanced,
    // preserving many medium gaps across the fleet).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: strongly reward if next item fits the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= next_item_size as f64 * 0.5;
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 8.0; // near-perfect chain fit
        }
    }
    // Penalize unusable leftover for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Dead-space shaping: tiny gaps are nearly useless.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 8.0 {
            score += 20.0 * (8.0 - r);
        } else if r <= 20.0 {
            score += 0.5 * (20.0 - r);
        } else {
            score -= 0.1 * (r - 20.0);
        }
    } else {
        score -= 20.0; // perfect fit reward
    }

    // Tightness reward: filling most of the bin's current space is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Open-bin pressure, relaxed late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.08 * (open_bins_count as f64).powf(1.2) * (1.0 - 0.5 * progress);

    // Last-chance bin: only bin that fits -> prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: cost of opening a fresh bin, offset by crowding
    // and by large next items needing fresh space.
    if bin_residual == bin_capacity {
        score += 18.0;
        score -= 0.35 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 0.25 * next_item_size as f64;
        }
        score -= 0.25 * fill_ratio * bin_capacity as f64;
    }

    // Mild residual balancing toward the mean.
    score += 0.03 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are unusable.
    let dead = post_residual == 0;
    if dead {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable gap -> heavy penalty
    } else if post_residual < 25 {
        score += 8.0;  // small gap, only fits smallest items
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but only when the fit is mediocre.
    if fill_ratio < 0.5 {
        score += (open_bins_count as f64) * 0.8;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // blocks the next item
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; dead-space penalties on open bins make bad fits lose.
        score = 55.0 - 0.5 * (open_bins_count as f64);
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // possible item (1..=100 range, but treat < 10 as likely dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Small unusable-ish gaps (cannot fit anything meaningful) get graded penalties.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Coupling with next item lookahead: reward leaving exactly enough room
    // for the next item (chained packing), penalize near-misses that strand space.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < 1.0 {
            score -= 250.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            score -= 40.0 - gap.min(40.0);
        } else {
            // next item won't fit here; the residual becomes dead space unless tiny
            score += gap.min(60.0) * 3.0;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open
    // bins, filling existing bins is cheap so slight reward.
    let obp = open_bins_count as f64;
    score += (obp - 2.0).max(0.0) * 6.0;

    // Prefer bins tighter than the mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild progression term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New-bin candidate: an empty bin has full residual; make it attractive only
    // when this would otherwise be a poor fit. Baseline penalty keeps it behind
    // good fits but ahead of dead-space-creating placements.
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.3 * progress);

    // Strong near-perfect fill reward
    if pr == 0.0 {
        score -= 40.0;
    } else if pr <= (item_size as f64) / 8.0 {
        score -= 9.0;
    }

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) as f64;
            score -= 30.0 + 42.0 * (1.0 - slack / cap);
            if pr == ni {
                score -= 30.0;
            }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 13.0 * (after_next / cap);
            } else if after_next >= next_item_size.max(1) as f64 {
                score -= 9.0 + 4.0 * (after_next / cap);
            }
        } else {
            // Penalize near-miss residuals that cannot host next item
            score += 9.0 * (pr / cap);
            let miss = (ni - pr) as f64;
            if miss < 22.0 {
                score += 0.45 * miss;
            }
        }
    }

    // Penalize dead slivers unlikely to host typical items (two bands)
    let dead = pr_norm;
    if dead > 0.0 && dead < 0.11 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 8.5 * (1.0 - dead / 0.11);
    } else if dead >= 0.11 && dead < 0.24 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0 * (1.0 - (dead - 0.11) / 0.13);
    }

    // Unique-fit preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 26.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.35 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.6 {
            score -= base + 14.0 * (1.0 - 2.0 * progress);
        } else {
            score += base;
            score += 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 3.0;
        }
        if progress > 0.65 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 4.0;
        }
        // Perfect two-item packing into a fresh bin
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 8.0;
        }
        // Avoid opening a bin whose leftover is a useless sliver
        if next_item_size > 0 && pr < next_item_size as f64 && pr < 0.10 * cap {
            score += 6.0;
        }
    } else {
        // Mild preference toward bins whose residual matches the running mean
        score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));
    }

    // Tightness bonus
    let tight = 1.0 - pr_norm;
    score -= 4.0 * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect 2-step match: item + next item fill the bin exactly.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits, penalize leftover gap after the lookahead pair.
            let gap = pr - nxt;
            score -= 25.0 - gap.min(40.0) * 0.45;
        } else {
            // Next item does not fit: penalize proportionally to how much it misses.
            let miss = nxt - pr;
            score += miss.min(80.0) * 0.35;
        }
        // Small nudge toward post_residual near the mean residual (keeps bins balanced).
        score += (pr - mean_residual).abs() * 0.05;
    } else {
        // Last item: just minimize post residual.
        score += 0.0;
    }

    // Penalize large dead space that likely becomes unusable (below typical item floor of 1..100).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 8.0; // tiny gap is fine, nearly full bin
    } else if pr >= 10.0 && pr < 25.0 {
        score += 3.0;
    } else if pr >= 25.0 {
        score += (pr - 25.0) * 0.30; // large residual wastes capacity
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a good fit (i.e., this bin is already empty) — otherwise discourage it.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No alternative: new bin is fine; give it a neutral-but-competitive score.
            score = (bin_capacity - item_size) as f64;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 20.0;
            }
        } else {
            // Open bins exist that fit; discourage opening a new one unless they fit badly.
            let worst_open = mean_residual.max(0.0);
            let slack = worst_open - item_size as f64;
            if slack < 12.0 {
                score = worst_open - item_size as f64 + pr * 0.5 - 10.0;
            } else {
                score = pr + 55.0;
            }
        }
    }

    // Slight stream-progression pressure: later in the stream, tighten bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

