        // penalize proportionally, but less if leftover is very small.
        let dead = post_residual as f64;
        score += 0.5 * dead;
        // If the dead space is unusable for typical small items, penalize harder
        if dead < 10.0 && dead > 0.0 {
            score += 30.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose post_residual sits below the
    // mean residual (driving tight bins toward closure, keeping loose bins flexible).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, using it avoids opening
    // a new bin — reward strongly unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has maximal residual. Only prefer it
    // when no open bin offers a good (tight) fit, i.e., penalize opening new bins
    // mildly, with the penalty shrinking as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 45.0 - 20.0 * progress;
        // If lookahead can't be satisfied by this fresh bin either, discourage less
        if next_item_size > 0 && next_item_size > bin_capacity as u32 - item_size {
            new_bin_penalty -= 10.0;
        }
        // Many open bins with large mean residual => plenty of slack exists, keep new bins closed
        if mean_residual > 30.0 {
            new_bin_penalty += 15.0;
        }
        score += new_bin_penalty;
    }

    // Mild waste aversion: quadratic-ish penalty on large post_residual to keep
    // fragments small, tempered by stream position (early stream tolerates slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * (post_residual as f64).powi(2) * (1.0 - 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space avoidance).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post-residuals that become "dead space": too small for typical items
    // (items range 1..=100, so residual < ~10 is nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual exactly or well;
    // penalize if next item cannot fit but could fit elsewhere.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty scaled by how much it overflows
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bins should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base new-bin cost: opening a bin is expensive early, cheaper late.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * (1.0 - progress);
        // If item leaves a large residual in the new bin (small item), extra penalty.
        let fill = item_size as f64 / (bin_capacity as f64);
        score += 10.0 * (1.0 - fill);
    } else {
        // Reward using bins whose residual is close to item size (good utilization).
        let fit_ratio = item_size as f64 / (bin_residual as f64);
        if fit_ratio <= 1.0 {
            score -= 8.0 * fit_ratio;
        }
        // Penalize drawing down bins far below the mean residual (keeps diversity of gaps).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global pressure: with many open bins, prefer consolidating into existing ones.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Late-stream consolidation: as the stream ends, favor filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.8 * progress * progress);
    score -= 0.6 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 1.2 * (ni / cap) * (1.0 - pr_norm);
        } else {
            score += 0.8 * ((ni - pr) / cap);
        }
    }
    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);
    if bin_residual == bin_capacity {
        score += 1.5 + 1.5 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.05;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (too small for typical items) get extra penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 100.0;
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: penalize spreading across many bins; encourage filling existing ones.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Penalize creating residual far below mean residual (wasteful fragmentation).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Near-match: next item fits with small leftover -> moderate reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - leftover / bin_capacity as f64);
    }

    // Dead space: post_residual too small for next item (wasted gap)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer filling it rather than wasting it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
        // But allow new bin if current bin would leave tiny unusable residue
        if post_residual > 0 && post_residual < 10 {
            score -= 70.0;
        }
    }

    // Prefer bins tighter than the mean residual (compact packing)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Late in stream: be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual gets extra bonus).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest conceivable item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Extra reward when the leftover exactly complements the next item.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Wasting capacity the next item could have used elsewhere.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many fitting bins: mild penalty to keep selection discriminative.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // New-bin candidate: opening a bin is attractive early, or when fit is poor
    // and many open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_bin_score = 30.0 - 20.0 * progress; // cheaper to open early
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 4.0;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // must open a bin anyway
        }
        if fragmentation > 25.0 {
            new_bin_score -= 5.0; // existing bins are fragmented; fresh bin helps
        }
        score += new_bin_score;
    }

    // Prefer fuller bins relative to the fleet average residual.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimizing post residual (tight fits), non-linearly.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Quadratic penalty for awkward dead space (mid-range residuals are least reusable).
    let norm_pr = pr / cap;
    let awkward = 4.0 * norm_pr * (1.0 - norm_pr); // peaks at pr = cap/2
    score += 18.0 * awkward * (0.5 + 0.5 * progress);

    // Reward very tight fits (small post residual) more aggressively over time.
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            let fit_quality = 1.0 - (slack / cap);
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins fit, more so early in the stream.
    if is_new_bin && fitting_bins_count > 0 {
        score += 30.0 + 40.0 * (1.0 - progress);
    }

    // Mild bonus for new bin when it would be near-perfectly filled by item + next item.
    if is_new_bin && next_item_size > 0 {
        let combo = item_size as f64 + next_item_size as f64;
        if combo <= cap {
            score -= 20.0 * (combo / cap) * (combo / cap);
        }
    }

    // Slight preference to keep bins balanced with the mean residual.
    score += 0.15 * (pr - mean_residual).abs();

    // Congestion: many open bins -> prefer consolidating into existing ones.
    if !is_new_bin {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Small classes (<=25) are "dead space" classes.
    let post_class = post_residual / 10; // 0..=10 harmonic buckets
    match post_class {
        0 => score += 30.0,               // 0-9: near-perfect fit, reward strongly
        1 => score += 8.0,                // 10-19: very good
        2 | 3 => score += 0.0,            // 20-39: neutral
        4 | 5 => score += 6.0,            // 40-59: mediocre leftover
        6 | 7 => score += 14.0,           // 60-79: large dead space risk
        _ => score += 22.0,               // 80-100: almost untouched bin, wasteful
    }

    // Exact-fill harmonic reward: post_residual in a tiny class is gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Modular compatibility: does post_residual pair with the next item's
    // size class? Reward if next item divides/lands into the leftover class.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into the leftover's harmonic bucket
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0; // chain of perfect fits
            } else if gap <= 10 {
                score -= 20.0;
            } else if gap <= 25 {
                score -= 5.0;
            } else {
                score += 4.0; // sloppy chain
            }
        } else {
            // next item cannot use this bin's leftover; leftover likely dead
            score += 10.0;
            if post_residual < 10 {
                score += 10.0; // tiny leftover that nothing (min size 1..) reuses well
            }
        }
    } else {
        // last item: just minimize leftover
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discourage opening new bins when plenty of open bins exist and the
    // new-bin candidate (residual == capacity) is not clearly better.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // new bin should only win if it enables a great future fit;
        // penalize mildly so tight fits in existing bins win first.
        score += 12.0;
        if open_bins_count == 0 {
            score -= 50.0; // nothing open: must use it
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    // Mean-residual coupling: if average leftover is small, protect tight fits.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A gap is "dead" if it is too small for any plausible future item (>= 1..100),
    // but practically items below ~12 are rare; treat gaps < 15 as near-dead.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0;
    }
    // Exact fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize very small residual decay nonlinearly (waste potential).
    let pr = post_residual as f64;
    score += 0.05 * pr * pr;

    // Open bins pressure: discourage spreading when many bins are open.
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.8;
    }

    // Last chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would be blocked by a tiny leftover, penalize.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 15 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when no good open option exists
    // (i.e., this empty bin call arrives with high mean residual fragmentation).
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 1.5;
        // early stream: allow opening bins more freely
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        // Exact match: perfectly closes the bin after the next item.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward by how close it is to filling the bin.
            let waste_after_next = post_residual - next_item_size;
            score -= 30.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item does NOT fit this bin's post-residual: penalize
            // proportionally to the leftover dead space we'd strand.
            score += 25.0 * (nxt - post) / bin_capacity as f64;
        }

        // Coupling with mean residual: prefer bins whose post-residual
        // deviates favorably (small) from the fleet mean.
        score += 0.5 * (post - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize large stranded post-residuals (dead space) super-linearly.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * frac * frac;

    // Mild bonus for tight fits overall (item nearly fills the bin).
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Late in the stream: consolidate more aggressively into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if the next item exactly fits the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 10.0 * tightness;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        score -= 0.5 * (open_bins_count as f64).ln();
        score -= 0.05 * mean_residual;
    }

    // New-bin candidate: make empty bins less attractive unless the item
    // is large relative to capacity or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 12.0 + 20.0 * (1.0 - large_item) - 15.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0; // nothing else fits, allow new bin
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual >= next_item_size {
            score -= 10.0; // room for the follow-up item too
        }
    }

    // Mild time-horizon coupling: early on, be picky (higher penalty on waste);
    // late in the stream, just pack anything.
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64 / cap;
    let fit = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: strong pressure to fill bins tightly (small post_residual favored).
    // Late stream: relax slightly, allow opening fresh bins for future flexibility.
    let tightness = 1.0 - 0.6 * progress * progress;
    score *= 1.0 + tightness * pr * pr;

    // Reward near-perfect fits with a smooth cubic bonus.
    let perfect = (1.0 - pr).powi(3);
    score -= 4.0 * perfect * (1.0 + progress);

    // Penalize large dead space superlinearly, more so when many bins are open.
    score += 2.0 * pr * pr * (open_bins_count as f64 / 8.0).min(2.0);

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
        score -= 3.0 * (1.0 - gap).powi(3);
        score += 2.0 * gap * gap;
    }

    // Last-chance bonus: smooth sigmoid-like weight when few fitting bins remain.
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).powi(2));
    score -= 5.0 * last_chance;

    // Mild penalty for opening a new bin when many open bins exist, scaled by progress.
    if bin_residual == bin_capacity {
        score += 1.5 + 3.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // But reward a new bin if the item is large and residual would be tiny anyway.
        score -= 2.0 * fit * fit * (1.0 - pr);
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.5 * (post_residual as f64 - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Class boundaries: post_residual in {0..5, 6..12, 13..25, 26..50, 51..} treated as
    // harmonic bins of "usefulness". Smaller usable leftovers are rewarded.
    let class: f64 = if post_residual == 0 {
        -30.0 // perfect fit: strong reward
    } else if post_residual <= 5 {
        -18.0 // near-perfect, dead space below minimum item size
    } else if post_residual <= 12 {
        -6.0
    } else if post_residual <= 25 {
        0.0
    } else if post_residual <= 50 {
        8.0
    } else {
        16.0 // large leftover: usually fine if bin was fresh, but penalize mid-life bins
    };

    // Modulo arithmetic on post_residual: residues divisible by common item granularities
    // (10, 20, 25) are more likely to be filled by future items.
    let harmonic_bonus: f64 = if post_residual % 10 == 0 {
        -5.0
    } else if post_residual % 25 == 0 {
        -3.5
    } else if post_residual % 20 == 0 {
        -3.0
    } else if post_residual % 5 == 0 {
        -1.5
    } else {
        0.0
    };

    // Lookahead coupling: if next item fits exactly into the post residual, big reward.
    let lookahead: f64 = if next_item_size > 0 {
        if next_item_size == post_residual {
            -12.0
        } else if next_item_size <= post_residual {
            // next item fits but leaves an awkward remainder
            let rem = post_residual - next_item_size;
            if rem <= 5 { -6.0 } else if rem % 10 == 0 { -4.0 } else { -1.0 }
        } else {
            // next item won't fit here: leftover becomes dead unless tiny
            if post_residual < 10 { -4.0 } else { 3.0 }
        }
    } else {
        0.0 // last item: just minimize waste
    };

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    let last_chance: f64 = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -10.0 + 0.15 * post_residual as f64
    } else {
        0.0
    };

    // New-bin candidate handling: empty bin starts from a neutral baseline so that
    // it only wins when open bins have bad fits.
    let new_bin_adjust: f64 = if bin_residual == bin_capacity {
        30.0 + 0.5 * open_bins_count as f64
    } else {
        0.0
    };

    // Tight-fit reward: prefer bins where the item occupies a large share of residual.
    let tightness: f64 = -2.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Progress-scaled waste penalty: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress_penalty: f64 = progress * frac * 6.0;

    // Pull toward mean residual: avoid creating outliers far below the mean
    // (fragmentation) but also discourage hoarding huge residuals.
    let mean_pull: f64 = 0.25 * (post_residual as f64 - mean_residual).abs();

    score += class + harmonic_bonus + lookahead + last_chance + new_bin_adjust
        + tightness + progress_penalty + mean_pull;

    score
}

