    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);

    // New-bin candidate: neutral baseline, only wins when fits are poor;
    // pressure grows with open bin count and stream progress.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.4 * open_bins_count as f64 + 2.0 * progress;
    }

    score
}

