    } else {
        0.0
    };

    // Last-chance pressure: only fitting bin should usually win.
    let last_chance: f64 = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -12.0 + 0.12 * post_residual as f64
    } else if fitting_bins_count == 2 && post_residual <= 10 {
        -4.0
    } else {
        0.0
    };

    // New-bin candidate: baseline rises with open-bin count and with how much
    // slack already exists across bins (avoid opening bins when slack abounds).
    let new_bin_adjust: f64 = if bin_residual == bin_capacity {
        28.0 + 0.4 * open_bins_count as f64 + 0.02 * mean_residual
    } else {
        0.0
    };

    // Tightness: fill ratio of the residual, saturating for near-full usage.
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tightness: f64 = -3.0 * ratio.min(1.0) - 1.0 * ratio.max(1.0);

    // Progress-scaled waste pressure with a mid-stream surge.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let surge = (progress * std::f64::consts::PI).sin();
    let progress_penalty: f64 = frac * (5.0 + 4.0 * surge);

    // Mean pull, softened by progress so late outliers matter less.
    let mean_pull: f64 = 0.2 * (post_residual as f64 - mean_residual).abs() * (1.0 - 0.5 * progress);

    // Fragmentation guard: penalize leftovers that no plausible item can fill
    // exactly (prime-ish residues above the smallest granularity).
    let frag: f64 = if post_residual > 7 && post_residual % 5 != 0 && post_residual % 10 != 0 {
        2.5
    } else {
        0.0
    };

    score += class + harmonic_bonus + lookahead + last_chance + new_bin_adjust
        + tightness + progress_penalty + mean_pull + frag;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post-residual: quantize dead space into usefulness bands.
    let class: f64 = if post_residual == 0 {
        -30.0 // perfect fit
    } else if post_residual <= 5 {
        -18.0 // dead space below plausible item granularity
    } else if post_residual <= 12 {
        -6.0
    } else if post_residual <= 25 {
        0.0
    } else if post_residual <= 50 {
        8.0
    } else {
        16.0
    };
    score += class;

    // Harmonic bonus: leftovers divisible by common item granularities refill easier.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 5.0;
        } else if post_residual % 25 == 0 {
            score -= 3.5;
        } else if post_residual % 20 == 0 {
            score -= 3.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        }
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size as u32 == post_residual {
            score -= 12.0; // exact chain fill
        } else if next_item_size as u32 <= post_residual {
            let rem = post_residual - next_item_size;
            if rem <= 5 {
                score -= 6.0;
            } else if rem % 10 == 0 {
                score -= 4.0;
            } else {
                score -= 1.0;
            }
        } else {
            // next item cannot use this leftover
            if post_residual < 10 {
                score -= 4.0;
            } else {
                score += 3.0;
            }
        }
    }

    // Tightness reward: filling a large share of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fill_ratio - 18.0 * fill_ratio * fill_ratio;

    // Last-chance bin: only fitting bin should absorb the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * post_residual as f64;
    }

    // New-bin candidate: neutral-to-costly baseline; wins only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // lookahead: fresh bin is more valuable if next item is large
        score -= 0.2 * next_item_size as f64;
        // if item nearly fills the fresh bin, opening is cheap
        score -= 0.3 * fill_ratio * cap;
    }

    // Progress-scaled waste penalty: waste matters more late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let frac = post_residual as f64 / cap;
    score += progress * frac * 6.0;

    // Mean-residual pull: discourage fragmentation outliers.
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Open-bin pressure: mild, decays with progress.
    score += 0.08 * (open_bins_count as f64).powf(1.3) * (1.0 - 0.5 * progress);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: if the next item cannot fit in the post residual,
    // this bin becomes a dead-end. Strong penalty proportional to wasted space.
    if post_residual < next_item_size {
        score += (post_residual as f64) * 1.5 + 10.0;
    } else {
        // Reward tight fits: small post residual relative to item size
        let tightness = post_residual as f64 / (item_size.max(1) as f64);
        score -= 3.0 / (1.0 + tightness);
    }

    // Lookahead: prefer bins where the next item also fits comfortably
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 2.0;
    }

    // New-bin candidate: make empty bins attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 2.5;
        // discourage opening new bins early in the stream
        score += (open_bins_count as f64).ln().max(0.0) * 1.0;
    }

    // Slight preference for filling bins with larger residual (avoid many near-empty bins)
    score += bin_residual as f64 * 0.02;

    // Progress-based tuning: later in the stream, be more conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize bins whose leftover would be a small unusable sliver
    // (dead space) unless the next item can use it.
    if post_residual > 0 && post_residual < next_item_size {
        // leftover can't host next item: penalize proportional to waste
        score += 12.0 * (next_item_size.saturating_sub(post_residual)) as f64 / bin_capacity as f64;
    } else if post_residual >= next_item_size && next_item_size > 0 {
        // leftover can host next item: reward keeping usable space
        score -= 8.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Prefer bins with residual close to item size (tight fit) mildly
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * tight;

    // When many bins can fit the item, favor the tightest (highest score reduction
    // for larger fitting count keeps selection stable); when few fit, prefer
    // spreading load to avoid fragmenting the last good bin.
    if fitting_bins_count <= 2 {
        score -= 5.0;
    }

    // New-bin candidate: make it attractive only when no open bin leaves
    // a comfortable residual for the next item.
    if bin_residual == bin_capacity {
        let open_tight = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual > (item_size as f64 + next_item_size as f64);
        if open_tight && step_index > 0 {
            score -= 3.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let fits_next = post_residual >= next_item_size;
    // Base: reward large post_residual (oracle minimizes score).
    let mut score = post_residual as f64;

    // Tightness bonus: strongly reward near-perfect fills.
    let tight = post_residual as f64 / bin_capacity as f64;
    if tight < 0.08 {
        score -= 12.0 * (0.08 - tight);
    }

    // Lookahead: if the next item fits in the leftover space, reward this bin
    // (keeps chains going); if leftover is unusable dead space, penalize mildly.
    if fits_next {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 2.0 + 0.05 * post_residual as f64;
    }

    // New-bin candidate: default strongly penalized so we reuse open bins,
    // but if the item would leave a tiny unusable gap in every open bin,
    // opening a fresh bin can be better.
    if is_new_bin {
        score += 60.0;
        // If item nearly fills a whole bin, opening a new bin is attractive.
        if item_size as f64 >= 0.85 * bin_capacity as f64 {
            score -= 55.0;
        }
        // If few bins can fit the item and next item is large, avoid wasting
        // a scarce fitting bin on a bad squeeze.
        if fitting_bins_count <= 2 && next_item_size > bin_capacity / 2 && !fits_next {
            score -= 25.0;
        }
    }

    // Slight preference to fill bins with smaller residual first when many
    // bins are open (compaction pressure).
    score -= 0.01 * open_bins_count as f64 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let fits_next = post_residual >= next_item_size;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: reward large post_residual (oracle minimizes score).
    let mut score = post;

    // Tightness bonus: strongly reward near-perfect fills (refined curve).
    let tight = post / cap;
    if tight < 0.10 {
        score -= 15.0 * (0.10 - tight);
    } else if tight < 0.20 {
        score -= 2.0 * (0.20 - tight);
    }

    // Lookahead: reward chain continuation; scale penalty by how much
    // dead space would be created relative to the stream's mean residual.
    if fits_next {
        score -= 4.5;
    } else if post_residual > 0 {
        // Dead space penalty grows when the leftover exceeds the typical
        // residual (i.e., it's unusually wasteful to strand this much).
        let excess = ((post - mean_residual).max(0.0)) / cap;
        score += 2.0 + 0.06 * post + 3.0 * excess;
    }

    // Next-item urgency: if the next item is large and would NOT fit here,
    // prefer bins where it would fit, to avoid fragmenting capacity.
    if !fits_next && next_item_size > bin_capacity / 3 {
        score += 0.03 * next_item_size as f64;
    }

    // New-bin candidate handling.
    if is_new_bin {
        score += 60.0;
        // Large item nearly filling a bin: opening fresh is attractive.
        if item_size as f64 >= 0.82 * cap {
            score -= 55.0;
        }
        // Scarce fitting options + big next item: don't burn a scarce bin.
        if fitting_bins_count <= 2 && next_item_size > bin_capacity / 2 && !fits_next {
            score -= 28.0;
        }
        // When many bins are open with slack, discourage new bins more.
        if open_bins_count > 8 && mean_residual > 0.15 * cap {
            score += 8.0;
        }
        // Late in the stream, prefer closing out bins tightly.
        if step_index as f64 > 0.8 * total_items as f64 {
            score -= 6.0;
        }
    }

    // Compaction pressure: prefer filling bins with smaller residual first.
    score -= 0.012 * open_bins_count as f64 * (cap - bin_residual as f64) / cap;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
