        }
    }

    // New-bin candidate: default strongly penalized so we reuse open bins,
    // but if the item would leave a tiny unusable gap in every open bin,
    // opening a fresh bin can be better.
    if is_new_bin {
        score += 60.0;
        // If item nearly fills a whole bin, opening a new bin is attractive.
        if item_size as f64 >= 0.82 * bin_capacity as f64 {
            score -= 55.0;
        }
        // If few bins can fit the item and next item is large, avoid wasting
        // a scarce fitting bin on a bad squeeze.
        if fitting_bins_count <= 2 && next_item_size > bin_capacity / 2 && !fits_next {
            score -= 25.0;
        }
        // When many bins are open and this item would leave a tiny gap in every
        // fitting bin, a fresh bin preserves flexibility for the future.
        if fitting_bins_count <= 3 && post_residual < next_item_size && post_residual < 12 {
            score -= 15.0;
        }
        // Early stream: keep bins openable, mild discount.
        if step_index < total_items / 10 {
            score -= 5.0;
        }
    }

    // Slight preference to fill bins with smaller residual first when many
    // bins are open (compaction pressure).
    score -= 0.015 * open_bins_count as f64 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

