    let tight = post_residual as f64 / bin_capacity as f64;
    if tight < 0.10 {
        score -= 14.0 * (0.10 - tight);
    }
    // Dead-space ratio penalty: unusable space (too small for the next item)
    // is weighted by how much of the bin it represents.
    if !fits_next && post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 6.0 * dead * dead * bin_capacity as f64;
    }

    // Lookahead: if the next item fits in the leftover space, reward this bin
    // (keeps chains going); scale the reward by how snugly the next item lands.
    if fits_next {
        score -= 4.0;
        let snug = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        if snug < 0.05 {
            score -= 3.0 * (0.05 - snug);
        }
    }

    // New-bin candidate: default strongly penalized so we reuse open bins,
    // but if the item would leave a tiny unusable gap in every open bin,
    // opening a fresh bin can be better.
    if is_new_bin {
        score += 60.0;
        // If item nearly fills a whole bin, opening a new bin is attractive.
        if item_size as f64 >= 0.85 * bin_capacity as f64 {
            score -= 55.0;
        }
        // If few bins can fit the item and next item is large, avoid wasting
        // a scarce fitting bin on a bad squeeze.
        if fitting_bins_count <= 2 && next_item_size > bin_capacity / 2 && !fits_next {
            score -= 25.0;
        }
        // If the current item leaves a very small gap and the next item cannot
        // use it, a fresh bin avoids stranding capacity in an existing bin.
        if post_residual > 0 && post_residual < next_item_size && post_residual < bin_capacity / 20 {
            score -= 18.0;
        }
    }

    // Slight preference to fill bins with smaller residual first when many
    // bins are open (compaction pressure).
    score -= 0.012 * open_bins_count as f64 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    // Late-stream compaction: as we approach the end, prefer tighter fits more
    // aggressively since there is less future to absorb slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 2.0 * (progress - 0.8) * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    }

