}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let fits_next = post_residual >= next_item_size && next_item_size > 0;

    // Base: reward large post_residual (oracle minimizes score).
    let mut score = post_residual as f64;

    // Strong tightness bonus: near-perfect fills are highly rewarded.
    let tight = post_residual as f64 / bin_capacity as f64;
    if tight < 0.08 {
        score -= 14.0 * (0.08 - tight);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Dead-space sliver penalty: unusable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: chain continuation bonus; penalize dead leftovers.
    if fits_next {
        score -= 6.0;
        let mult = post_residual / next_item_size.max(1);
        if mult >= 2 {
            score -= 3.0 * mult as f64;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 2.0 + 0.05 * post_residual as f64;
    }

    // Harmonic class complementarity (from parent, softened).
    let third = bin_capacity / 3;
    let item_class = if item_size > bin_capacity - third { 2 } else if item_size >= third { 1 } else { 0 };
    let next_class = if next_item_size == 0 { 99 } else if next_item_size > bin_capacity - third { 2 } else if next_item_size >= third { 1 } else { 0 };
    if item_class == 2 && next_class == 2 {
        score += 8.0;
    }

    // Compaction pressure: prefer filling bins with smaller residual when many open.
    score -= 0.01 * open_bins_count as f64 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    // New-bin candidate: penalized by default; open when item nearly fills a bin
    // or when squeezing would leave tiny gaps everywhere.
    if is_new_bin {
        score += 60.0;
        if item_size as f64 >= 0.85 * bin_capacity as f64 {
            score -= 55.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if fitting_bins_count <= 2 && next_item_size > bin_capacity / 2 && !fits_next {
            score -= 25.0;
        }
        // If mean residual across open bins can't comfortably host the item,
        // a fresh bin is preferable.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: favor using the only fitting bin.
    if !is_new_bin {
        if fitting_bins_count == 1 {
            score -= 30.0;
        } else if fitting_bins_count > 1 {
            score += 3.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // Mild progress tie-break toward consolidation late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress;

    // Deterministic geometric tie-break.
    score += (post_residual % 7) as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Core: minimize post_residual (best-fit backbone, proven best performer)
    let mut score = post_residual as f64;

    // Gentle lookahead: if next item fits the leftover, this is a great pairing
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 1.5;
    }

    // Penalize leaving a tiny unusable sliver (wasted dead space)
    if post_residual > 0 && post_residual < 4 {
        score += 6.0;
    }

    // Reward exact fills
    if post_residual == 0 {
        score -= 3.0;
    }

    // Last-chance bin: mild preference to avoid opening new bins unnecessarily
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // New empty bin candidate: only attractive when nothing else fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so it loses to any reasonable existing fit
        score += 8.0;
        // But if no open bin fits, opening a new bin is required/necessary
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // If mean residual is large (bins are empty-ish), discourage new bins
        if mean_residual > item_size as f64 * 2.0 {
            score += 4.0;
        }
    }

    // Tiny deterministic tie-break
    score += (post_residual % 5) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward bins whose leftover after placement can still host the next item
    // (lookahead compaction): subtract to reward, so low post_residual that
    // still fits next_item wins; dead space that fits nothing is penalized.
    if post_residual >= next_item_size {
        score -= 2.0 + (post_residual - next_item_size) as f64 * 0.05;
    } else {
        // Dead space penalty scaled by how early in the stream we are
        let urgency = 1.0 + (step_index as f64 / total_items.max(1) as f64) * 0.5;
        score += (next_item_size - post_residual) as f64 * 0.02 * urgency;
    }

    // Mild bonus for tight fits relative to capacity
    let tightness = item_size as f64 / bin_capacity.max(1) as f64;
    score -= tightness * 0.3;

    // Prefer bins with residuals close to the item (best-fit refinement),
    // but relax when few bins can fit the item (avoid fragmenting options)
    let gap = (bin_residual - item_size) as f64;
    if fitting_bins_count > 1 {
        score -= 1.0 / (1.0 + gap);
    }

    // New-bin candidate: keep it unattractive unless open bins are all poor fits
    if bin_residual == bin_capacity {
        score += 3.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose leftover can still host the next item,
    // penalize bins that leave dead space the next item cannot use.
    if post_residual >= next_item_size {
        score -= 0.5 * (post_residual - next_item_size) as f64;
    } else {
        // dead space: leftover smaller than next item is likely wasted
        score += 0.35 * post_residual as f64;
    }

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= bin_capacity as f64;
    }

    // Tight-fit reward: item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.85 {
        score -= 2.0 * fill_ratio;
    }

    // When many bins can fit the item, prefer the tightest one (low post_residual
    // already does this); when only one bin fits, keep it attractive to avoid
    // opening a wasteful new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 1.5;
    }

    // New-bin candidate: only open a fresh bin if existing fits are poor.
    if bin_residual == bin_capacity {
        // mild penalty so a new bin is chosen only when open bins leave
        // large unusable residuals (their dead-space penalty exceeds this)
        score += 0.25 * bin_capacity as f64;
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            // big next item: a fresh bin is more acceptable
            score -= 0.1 * bin_capacity as f64;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: subtract more when the leftover is tiny.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that the next item cannot use (lookahead).
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            score -= 0.15 * (post_residual - next_item_size).min(30) as f64;
        }
    }

    // New-bin candidate: make it unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if current bins are all badly fragmented, allow opening a fresh bin.
        if fitting_bins_count <= 1 && post_residual as f64 > cap * 0.5 {
            score -= 45.0;
        }
    }

    // Mild pressure against scattering items across many bins when few remain.
    if fitting_bins_count > 2 {
        score -= 1.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize
    // "too tight" dead space that can never be reused.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else {
        let slack = post_residual as f64;
        // Penalize small unfillable slivers (< next_item_size and small in general)
        if post_residual < next_item_size {
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.25;
        }
        // Mild bonus for leaving room for the next item
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 2.0;
        }
        // Penalize large waste relative to capacity
        let waste_ratio = slack / bin_capacity as f64;
        score += waste_ratio * 8.0;
    }

    // Lookahead: if many bins can fit this item, prefer spreading less;
    // if only one bin fits, strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large relative to capacity, opening a fresh bin
        // can be reasonable; soften the penalty.
        if item_size * 2 >= bin_capacity {
            score -= 12.0;
        }
        // When few bins remain usable, discourage opening new bins more.
        if fitting_bins_count <= 2 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64;

