    }

    // New-bin candidate: only attractive when open bins would leave large waste.
    if bin_residual == bin_capacity {
        let avg_waste = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else { 0.0 };
