}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.8 * progress * progress);
    score -= 0.6 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);

    // Stronger lookahead: reward bins whose leftover hosts the next item,
    // scaled by how much of the next item's demand is covered.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= (ni / cap) * (1.2 + 0.6 * (1.0 - progress));
        } else {
            // Dead space: penalize waste proportional to shortfall.
            score += ((ni - pr) / cap) * (0.8 + 0.7 * progress);
        }
    }

    // Tight-fit preference when several bins compete.
    if fitting_bins_count > 1 {
        let slack = (bin_residual - item_size) as f64;
        score += 0.12 * (slack / cap);
    }

    // Unique-fit bins are precious: keep them attractive early.
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    // Mild pressure against fragmenting across many open bins.
    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);

    // New-bin candidate: attractive only if all open fits would waste a lot,
    // e.g. when mean residual can't even host the next item.
    if bin_residual == bin_capacity {
        let waste_if_open = (mean_residual - item_size as f64).max(0.0) / cap;
        let penalty = 1.5 + 1.5 * progress - 2.0 * waste_if_open;
        score += penalty.max(0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
