    let mut score = pr * 0.6 + pr_norm * (1.0 + 0.4 * progress * progress);

    // Reward tight fits (low post residual) more aggressively early on
    score -= 0.8 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);

    // Strong lookahead: if the next item fits in the leftover space, reward heavily
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 1.5 * (ni / cap) * (1.0 - pr_norm);
        } else {
