        }
    }

    // If this is the only fitting bin, strongly prefer it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    // Penalize spreading across many open bins slightly
    score += 0.35 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);

    // New empty bin: penalize so it's only chosen when truly better
    if bin_residual == bin_capacity {
        score += 2.0 + 1.5 * progress;
    }

    // Bonus for nearly perfect fills
    if pr == 0.0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
