    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            // strong lookahead: reward bins that can also host the next item
            score -= 1.8 * (ni / cap) * (1.0 - pr_norm);
            // perfect chain (residual exactly consumed by next item)
            if (pr - ni).abs() < 0.5 {
                score -= 0.8;
            }
        } else {
            score += 0.9 * ((ni - pr) / cap);
        }
