    }
    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);
    if bin_residual == bin_capacity {
        // new bin: cheaper to open early when many items remain and many bins fit
        let pressure = (fitting_bins_count as f64 / 8.0).min(1.0);
        score += 1.5 + 1.5 * progress - 0.7 * pressure * (1.0 - progress);
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
