    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 8.0 {
            score += 25.0 * (8.0 - r); // punish tiny dead gaps
        } else if r <= 20.0 {
            score += 0.6 * (20.0 - r); // small recoverable gaps
        } else {
            score -= 0.15 * (r - 20.0); // large flexible leftovers get mild bonus
        }
    } else {
        score -= 25.0; // perfect fit reward
    }

    // Tightness reward: filling most of the bin's current space is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Lookahead: reward if next item fits the leftover (with decay on slack).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * 0.5;
