    if pr > 0.0 && pr < sliver_threshold {
        score += (sliver_threshold - pr) * 0.55;
    }

    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 1.2 * (ni / cap) * (1.0 - pr_norm);
            // Bonus: residual can host next item twice over
            if pr >= 2.0 * ni {
                score -= 0.8 * (1.0 - progress);
            }
        } else {
            score += 0.8 * ((ni - pr) / cap);
        }
    }

    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);

    if bin_residual == bin_capacity {
        // Opening a new bin is fine when nothing fits well, but penalize
        // when good alternatives exist
        if fitting_bins_count > 1 {
            score += 1.5 + 1.5 * progress + 0.8 * (1.0 - pr_norm);
        } else {
            score += 0.6;
        }
    }

    // Prefer near-perfect fits slightly more
    if post_residual == 0 {
        score -= 1.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    // Reward leaving room for the next item, scaled by how tight the fit is
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        score -= next_item_size as f64 * (0.5 + 0.15 * (1.0 - slack / bin_capacity as f64).min(1.0)) ;
    }
    // Penalize near-miss residuals that cannot host the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3 ;
    }
    // Penalize dead slivers that are unlikely to host typical items
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.7 ;
    }
    // Reward bins that retain capacity for two more mid-size items
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        score -= 2.0 ;
    }
    // Extra reward for near-perfect fills (post residual tiny but nonzero)
    if post_residual > 0 && post_residual <= item_size / 8 {
        score -= 1.0 ;
    }
    // Penalize opening a new bin when open bins can still fit, stronger when many are open
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(0.5) ;
        score += 1.5 + 2.0 * pressure ;
