        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.5 ;
        }
    }
    // Mild tie-break toward bins with residual close to the running mean (keeps spread tight)
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / (bin_capacity as f64)).min(1.0)) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: tiny gaps are nearly useless.
    if post_residual > 0 {
        let r = post_residual as f64;
        if r < 8.0 {
            score += 25.0 * (8.0 - r);
        } else if r <= 20.0 {
            score += 0.6 * (20.0 - r);
        } else {
            score -= 0.15 * (r - 20.0);
        }
    } else {
        score -= 25.0;
    }

    // Tightness reward: filling most of the bin's current space is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Lookahead: reward if next item fits the leftover, scaled by tightness of the chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let tightness = 1.0 - slack / bin_capacity as f64;
        score -= next_item_size as f64 * (0.5 + 0.15 * tightness.min(1.0));
        if slack < 12.0 {
            score -= 10.0;
        }
        // Room for a second copy of the next item: strong chain potential.
        if post_residual >= 2 * next_item_size {
            score -= 2.5;
        }
    }
    // Penalize if next item cannot use this leftover and leftover is mid-sized.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 35 {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure, relaxed late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.1 * (open_bins_count as f64).powf(1.2) * (1.0 - 0.5 * progress);

    // Last-chance bin: only bin that fits -> prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: cost of opening a fresh bin, offset by crowding
    // and by large next items needing fresh space.
    if bin_residual == bin_capacity {
        score += 20.0;
        score -= 0.4 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64;
        }
        score -= 0.3 * fill_ratio * bin_capacity as f64;
        // If the only fitting open bins would leave bad slivers, allow a fresh bin.
        if fitting_bins_count <= 1 && next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.5;
        }
    }

    // Residual balancing toward the mean (keeps spread tight, aids future fits).
    let dev = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs().min(1.0);
    score += 0.04 * (mean_residual - bin_residual as f64);
    score -= 0.6 * (1.0 - dev);

    // Near-perfect fill bonus: leftover just barely below item granularity.
    if post_residual > 0 && post_residual <= item_size / 8 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
