    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    // Lookahead synergy: strong reward when next item consumes the leftover,
    // weighted by next item size and closeness of fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.5 + 0.15 * (1.0 - slack / cap).min(1.0));
        if slack < 10.0 {
            score -= 12.0;
        }
    }
    // Penalize when next item cannot use a mid-sized leftover.
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: fewer new bins when crowded, relaxed late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).powf(1.3) * (1.0 - 0.5 * progress);
    score += 0.15 * pressure;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: costly unless crowded or next item is large.
    if bin_residual == bin_capacity {
        score += 25.0;
        score -= 0.35 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 0.25 * next_item_size as f64;
        }
        score -= 0.4 * fill_ratio * cap;
    }

    // Residual-balance term: prefer bins near the fleet mean, keeping gaps usable.
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    // Reward leaving room for the next item, scaled by tightness of fit
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 ;
        score -= next_item_size as f64 * (0.5 + 0.16 * (1.0 - slack / bin_capacity as f64).min(1.0)) ;
    }
    // Penalize near-miss residuals that cannot host the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3 ;
    }
    // Penalize dead slivers unlikely to host typical items
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.7 ;
    }
    // Lookahead: strongly reward residuals that can host the next item twice
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < bin_capacity {
        score -= 1.4 ;
    }
    // Lookahead: mild reward for hosting next item plus a small filler
    if next_item_size > 0 && post_residual >= next_item_size * 3 / 2 && post_residual < 2 * next_item_size {
        score -= 0.5 ;
    }
    // Reward near-perfect fills
    if post_residual > 0 && post_residual <= item_size / 8 {
        score -= 0.9 ;
    }
    // New-bin penalty, modulated by open-bin pressure
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(0.5) ;
        score += 1.5 + 2.0 * pressure ;
        // Allow a new bin when open fits would create bad slivers or no good fit exists
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.2 ;
        }
    }
    // Tight-spread tie-break toward residual near running mean
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / (bin_capacity as f64)).min(1.0)) ;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fills strongly
    if post_residual == 0 {
        score -= 2.0 * cap;
    }

    // Lookahead: reward bins that can still host the next item, scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let tight = 1.0 - (slack / cap).min(1.0);
        score -= next_item_size as f64 * (0.55 + 0.2 * tight);
    }

    // Penalize bins that become dead space (too small for next item but not zero)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Penalize small dead residuals (fragmentation) with a sharper threshold
    if post_residual > 0 && post_residual < bin_capacity / 8 {
        score += (bin_capacity as f64 / 8.0 - post_residual as f64) * 0.8;
    }

    // Mild preference for bins deviating from the mean residual (diversity of fill levels)
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // When many bins fit the item, prefer tighter fits more aggressively
    if fitting_bins_count > 2 {
        score -= (fitting_bins_count.min(8) as f64) * (post_residual as f64 / cap) * 0.15;
    }

    // New-bin candidate: penalize opening a new bin unless it is truly needed
    if bin_residual == bin_capacity {
        score += 1.5 * cap * (1.0 - (item_size as f64 / cap));
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead reward: prefer bins where the next item also fits with tight slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.5 + 0.15 * (1.0 - slack / cap).min(1.0));
    }

    // Penalize near-miss residuals that waste space for the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize small dead-space residuals (wasted slivers)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.7;
    }

    // Mild deviation term
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // NEW: reward bins that become exactly tight after placement (perfect fits)
    if post_residual == 0 {
        score -= item_size as f64 * 0.25;
    }

    // NEW: prefer bins whose residual before placement is a near multiple of the item,
    // enabling repeated placements and reduced fragmentation
    if item_size > 0 && bin_residual >= item_size {
        let reps = bin_residual / item_size;
        if reps >= 2 {
            score -= 0.35 * (reps.min(4) as f64);
        }
    }

    // NEW: when many bins can fit this item, favor the emptiest usable one to
    // preserve tight bins for future tight items
    if fitting_bins_count > 2 && bin_residual < bin_capacity {
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.2 * (post_residual as f64 / cap);
    }

    // NEW: early-stream bias toward keeping bins balanced (mild), fading over time
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if progress < 0.3 {
        score += 0.4 * (1.0 - progress / 0.3) * ((bin_residual as f64 / cap) - 0.5).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let mut score = r;

    // Dead-space avoidance: tiny gaps are nearly useless (sharper curve).
    if post_residual > 0 {
        if r < 8.0 {
            score += 30.0 * (8.0 - r);
        } else if r <= 20.0 {
            score += 0.7 * (20.0 - r);
        } else {
            score -= 0.18 * (r - 20.0);
        }
    } else {
        score -= 30.0; // perfect fit reward
    }

    // Tightness reward: filling most of the bin's current space is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Lookahead: reward if next item fits the leftover, scaled by slack tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let tight = (1.0 - slack / cap).min(1.0);
        score -= next_item_size as f64 * (0.5 + 0.2 * tight);
        if slack < 10.0 {
            score -= 12.0; // near-perfect chain fit
        }
    }
    // Penalize if next item cannot use this leftover and leftover is mid-sized.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 40 {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure, relaxed late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.12 * (open_bins_count as f64).powf(1.2) * (1.0 - 0.5 * progress);

    // Last-chance bin: only bin that fits -> prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: cost of opening a fresh bin, offset by crowding
    // and by large next items needing fresh space.
    if bin_residual == bin_capacity {
        score += 22.0;
        score -= 0.45 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 0.35 * next_item_size as f64;
        }
        score -= 0.3 * fill_ratio * cap;
    }

    // Residual balancing toward the mean, softly.
    score += 0.05 * (mean_residual - r);

    // Mean-deviation shaping (borrowed idea): prefer residuals near mean.
    score -= 0.06 * (1.0 - ((r - mean_residual).abs() / cap).min(1.0));

    // Waste-anticipation: if this bin's post-residual is small AND next item
    // is large, opening fresh space may pay off — soften penalty on new bins.
    if bin_residual == bin_capacity && next_item_size > post_residual && next_item_size as f64 > 0.6 * cap {
        score -= 8.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
