    }

    // Penalize near-miss residuals that waste space for the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize small dead-space residuals (wasted slivers)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (cap / 10.0 - post_residual as f64) * 0.7;
    }

    // Mild deviation term
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Reward perfect fits (bin closed exactly)
    if post_residual == 0 {
        score -= item_size as f64 * 0.2;
    }

    // Reward bins that can host the item multiple times (fragmentation reduction)
    if item_size > 0 && bin_residual >= item_size {
        let reps = bin_residual / item_size;
        if reps >= 2 {
            score -= 0.3 * (reps.min(4) as f64);
        }
    }

    // When many bins fit the item, prefer emptier ones (preserve tight bins),
    // but only in mid/late stream so early bins stay balanced
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if fitting_bins_count > 2 && bin_residual < bin_capacity && progress > 0.15 {
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.15 * (post_residual as f64 / cap);
    }

    // Early-stream balance bias, fading over time
    if progress < 0.25 {
        score += 0.3 * (1.0 - progress / 0.25) * ((bin_residual as f64 / cap) - 0.5).abs();
    }

    // Late-stream: strongly close bins down (compaction) — avoid spreading residue
    if progress > 0.7 && post_residual > 0 && post_residual < next_item_size.max(1) {
        score += post_residual as f64 * 0.4;
    }

    // Mild penalty for opening a new bin when open bins exist with decent fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 2.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.8 * progress * progress);
    score -= 0.6 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = pr - ni;
            score -= ni * (0.5 + 0.15 * (1.0 - (slack / cap).min(1.0))) / cap.max(1.0) * cap / cap;
            score -= 1.2 * (ni / cap) * (1.0 - pr_norm);
        } else {
            score += 0.8 * ((ni - pr) / cap);
        }
    }
    // penalize tiny leftover residuals (wasted space)
    if pr > 0.0 && pr < cap / 10.0 {
        score += (cap / 10.0 - pr) * 0.7 / cap.max(1.0) * 10.0;
    }
    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);
    // mild deviation-from-mean tiebreaker
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));
    if bin_residual == bin_capacity {
        score += 1.5 + 1.5 * progress;
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead reward: bin remains usable by the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.5 + 0.18 * (1.0 - slack / cap).min(1.0));
    }

    // Penalty when placing here strands the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * (0.3 + 0.2 * (waste / cap));
    }

    // Penalize small dead-space residuals (hard to reuse later)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.75;
    }

    // Perfect-fit bonus: exact fill is always optimal
    if post_residual == 0 {
        score -= cap * 0.5;
    }

    // Deviation from mean residual: mildly prefer typical-load bins
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Scarcity coupling: when few bins can fit the item, reward whichever
    // bins can (keeps scarce large-capacity options from being wasted),
    // but soften this when many bins fit (choice is easy).
    if fitting_bins_count > 0 && bin_residual < bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= scarcity * (item_size as f64 / cap) * 0.6;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // relative to capacity or open bins are nearly saturated.
    if bin_residual == bin_capacity {
        let load_pressure = (item_size as f64 / cap) * (1.0 + (open_bins_count as f64).ln().max(0.0) * 0.05);
        score += cap * (0.35 - load_pressure.min(0.3));
    }

    score
}

pub fn score_bin ( item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize ) -> f64 {
