    let fill_ratio = 1.0 - ( bin_residual as f64 / cap ) ;
    score -= 0.35 * fill_ratio * fill_ratio ;

    // Penalize opening a new bin when open bins exist and item fits well
    if bin_residual == bin_capacity && fitting_bins_count > 0 && item_size <= bin_residual {
        let best_fit_gap = mean_residual - item_size as f64 ;
        if best_fit_gap > 0.0 {
