    if pr > 0.0 && pr < cap / 10.0 {
        score += (cap / 10.0 - pr) * 0.7;
    }

    // Prefer bins near the mean residual (balanced filling)
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Unique-fit bins are precious
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    // Slight penalty for spreading across many open bins
    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);

    // New-bin candidate: open only when no open bin fits well
    if bin_residual == bin_capacity {
        let best_possible = if fitting_bins_count > 0 { 0.4 } else { 0.0 };
        score += 1.2 + 1.5 * progress + best_possible;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
