}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item,
    // with a tighter coupling when the fit is snug (small slack).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let snug = 1.0 - (slack / cap).min(1.0);
        score -= next_item_size as f64 * (0.55 + 0.20 * snug);
    }

    // Penalize bins that become dead (post_residual too small for next item).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let dead_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        score += (next_item_size - post_residual) as f64 * (0.30 + 0.25 * dead_frac);
    }

    // Discourage leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (cap / 10.0 - post_residual as f64) * 0.75;
    }

    // Mild diversity term relative to mean residual.
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // New-bin candidate handling: prefer opening a fresh bin only when the
    // item fits poorly everywhere and the new bin keeps room for the next item.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        // A fresh bin is attractive when the item is large (few wasted corners)
        // and few bins can host the item at all.
        let scarcity = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        score = post_residual as f64 - fill * cap * (0.25 + 0.35 * scarcity);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 0.15 * next_item_size as f64;
        }
    }

    // When many bins can fit the item, slightly favor tightening (lower score)
    // for bins whose post_residual is closest to the next item size — better
    // fragmentation control across the stream.
    if fitting_bins_count > 2 && next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.10 * (1.0 - ((post_residual - next_item_size) as f64 / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr_norm * (1.0 + 0.8 * progress * progress);
    score -= 0.6 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = pr - ni;
            // reward bins that leave a tight-but-usable remainder for the next item
            let tightness = 1.0 - (slack / cap).min(1.0);
            score -= ni * (0.5 + 0.15 * tightness) / cap;
        } else {
            score += 0.8 * ((ni - pr) / cap);
        }
    }
    // penalize very small post-residuals (wasted slivers)
    if pr > 0.0 && pr < cap / 10.0 {
        score += (cap / 10.0 - pr) * 0.7 / cap;
    }
    // prefer bins whose residual is close to the mean residual (keeps bin states uniform)
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));
    score += 0.3 * pr_norm * pr_norm * (open_bins_count as f64 / 10.0).min(1.0);
    if bin_residual == bin_capacity {
        score += 1.5 + 1.5 * progress;
    }
    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead reward: prefer bins where the next item also fits with tight slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.5 + 0.15 * (1.0 - slack / cap).min(1.0));
    }

    // Penalize near-miss residuals that waste space for the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize small dead-space residuals (wasted slivers)
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.7;
    }

    // Mild deviation term
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Reward bins that become exactly tight after placement (perfect fits)
    if post_residual == 0 {
        score -= item_size as f64 * 0.25;
    }

    // Prefer bins whose residual before placement is a near multiple of the item,
    // enabling repeated placements and reduced fragmentation
    if item_size > 0 && bin_residual >= item_size {
        let reps = bin_residual / item_size;
        if reps >= 2 {
            score -= 0.35 * (reps.min(4) as f64);
        }
    }

    // When many bins can fit this item, favor the emptiest usable one to
    // preserve tight bins for future tight items
    if fitting_bins_count > 2 && !is_new_bin {
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.2 * (post_residual as f64 / cap);
    }

    // Early-stream bias toward keeping bins balanced (mild), fading over time
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if progress < 0.3 {
        score += 0.4 * (1.0 - progress / 0.3) * ((bin_residual as f64 / cap) - 0.5).abs();
    }

    // NEW-BIN DECISION: open a fresh bin only when the item would leave a bad
    // dead-space sliver in every open bin, or no open bin fits at all.
    // Reward a new bin when item is large relative to capacity or when
    // fragmentation pressure is high (many open bins with tiny residuals).
    if is_new_bin {
        let frag = if open_bins_count > 0 {
            mean_residual / cap
        } else { 0.0 };
        // High mean residual => open bins are roomy; prefer reusing them.
        score += frag * cap * 0.3;
        // Small items should not trigger new bins early on.
        let item_frac = item_size as f64 / cap;
        if item_frac < 0.25 {
            score += (0.25 - item_frac) * cap * 0.5;
        }
        // Late in the stream, opening a bin is safer against fragmentation
        // if the next item is large and nothing tight is available.
        if progress > 0.7 && next_item_size as f64 / cap > 0.5 {
            score -= cap * 0.05;
        }
        // If very few open bins can fit the item, a new bin is a good hedge.
        if fitting_bins_count <= 1 {
            score -= cap * 0.1;
        }
    }

    // NEW: chain-fit bonus — if placing here lets the next item land perfectly
    // (post_residual == next_item_size), strongly prefer this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= next_item_size as f64 * 0.4;
    }

    // NEW: penalize leaving residuals in the awkward 10-25% band that rarely
    // accepts future items but wastes capacity.
    if post_residual > bin_capacity / 10 && post_residual < bin_capacity / 4 {
        score += 0.15 * (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead reward: prefer bins where next item also fits, weighted by tightness of the double fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let tight = 1.0 - (slack / cap).min(1.0);
        score -= next_item_size as f64 * (0.5 + 0.2 * tight);
        // extra bonus when the pair leaves almost nothing (perfect two-item fill)
        if slack < cap * 0.05 {
            score -= 1.5;
        }
    }

    // Penalize bins that become dead ends for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Dead-space penalty: small residuals that likely can never be used.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.8;
    }

    // Mild preference for bins whose fill level deviates from the mean (keeps bin states diverse).
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // When many bins can fit the item, favor tighter fits more strongly (competition signal).
    if fitting_bins_count > 3 {
        score -= 0.5 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64).min(1.0));
    }

    // Prefer opening a new bin early in the stream when the current fit is loose.
    if bin_residual == bin_capacity {
        // new-bin candidate: neutral baseline, slightly attractive when fit would be very loose
        let fit_ratio = item_size as f64 / cap;
        if fit_ratio < 0.5 && open_bins_count > 2 {
            score -= 0.8;
        } else {
            score += 0.5;
        }
    }

    score
}

