pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // lookahead: reward bins that can also host the next item tightly
    if next_item_size > 0 && post_residual >= next_item_size {
        let ni = next_item_size as f64;
        let slack = (post_residual - next_item_size) as f64;
        let tightness = 1.0 - (slack / cap).min(1.0);
        score -= ni * (0.5 + 0.25 * tightness);
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - pr) * 0.3;
    }

    // penalize slivers of dead space
    if pr > 0.0 && pr < cap / 10.0 {
        score += (cap / 10.0 - pr) * 0.7;
    }

    // keep bin states uniform
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // mild progress-aware compaction pressure
    score -= 0.4 * pr_norm * (1.0 - progress);

    // unique-fit bonus
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    // new-bin candidate: strongly discourage unless open bins are scarce or fit is perfect
    if bin_residual == bin_capacity {
        let perfect = item_size as f64 >= cap * 0.9;
        score += 1.5 + 1.5 * progress;
        if perfect {
            score -= 2.0;
        }
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

