    }

    // Mild deviation term
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Reward bins that become exactly tight after placement (perfect fits)
    if post_residual == 0 {
        score -= item_size as f64 * 0.25;
    }

    // Prefer bins whose residual supports repeated placements (less fragmentation)
    if item_size > 0 && bin_residual >= item_size {
        let reps = bin_residual / item_size;
        if reps >= 2 {
            score -= 0.35 * (reps.min(4) as f64);
        }
    }

    // NEW: exact-fit lookahead — if the next item exactly fills the post-residual,
    // strongly reward this chain placement
    if next_item_size > 0 && post_residual == next_item_size {
        score -= next_item_size as f64 * 0.35;
    }

    // NEW: two-item lookahead packing — reward when post-residual can hold the next
    // item plus a small remainder, reducing dead space across two steps
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        if after > 0 && after < item_size {
            score -= after as f64 * 0.4;
        }
    }

    // NEW: new-bin opening control — only open a new bin when no open bin gives a
    // tight fit; discourage the fresh-bin candidate unless residuals are all large
    if bin_residual == bin_capacity {
        // fresh bin penalty scaled by how many open bins can already fit the item
        if fitting_bins_count > 0 {
            let tightest = if post_residual > 0 { post_residual as f64 } else { cap };
            let tightness = 1.0 - tightest / cap;
            score += cap * (0.25 + 0.5 * tightness) + 2.0 * (fitting_bins_count as f64).ln();
        } else {
            score += cap * 0.05;
        }
    }

    // Late-stream compaction: as the stream ends, aggressively prefer the fullest
    // usable bins to squeeze out remaining space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
