    } else if progress < 0.3 {
        // early-stream balance bias (mild), fading over time
        score += 0.4 * (1.0 - progress / 0.3) * ((bin_residual as f64 / cap) - 0.5).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // lookahead: reward bins that leave a tight-but-usable remainder for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let slack = pr - ni;
            let tightness = 1.0 - (slack / cap).min(1.0);
            score -= ni * (0.5 + 0.15 * tightness);
        } else if pr > 0 {
            score += (ni - pr) * 0.3;
        }
    }

    // penalize very small post-residuals (wasted slivers)
    if pr > 0.0 && pr < cap / 10.0 {
        score += (cap / 10.0 - pr) * 0.7;
    }

    // prefer bins whose residual is close to the mean residual
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // progress-aware compaction pressure: push toward tight fits late in the stream
    score += pr_norm * pr_norm * cap * (0.2 + 0.5 * progress);

    // strong reward when this bin is the only one that fits (avoid losing it)
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - progress);
    }

    // exact fit bonus
    if post_residual == 0 {
        score -= 3.0;
    }

    // new-bin candidate: make it unattractive unless no good fit exists
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 1.5 + 1.5 * progress + 4.0 * desperation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: leftover gaps smaller than the smallest
    // plausible next demand are nearly unusable -> penalize them hard.
    if post_residual > 0 {
        let min_useful = (next_item_size.min(15)).max(1) as f64;
        let pr = post_residual as f64;
        if pr < min_useful {
            // The smaller (and thus more "dead") the gap, the bigger the penalty.
            score += (min_useful - pr) * 4.0 + 6.0;
        }
        // Medium dead zones: gaps below ~10 are risky for unknown distributions.
        if pr < 10.0 {
            score += (10.0 - pr) * 1.5;
        }
    }

    // Lookahead: reward placements that still leave room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, use it
    // rather than fragmenting the stream across new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer reusing existing bins
    // and penalize the brand-new empty bin candidate.
    if bin_residual == bin_capacity {
        score += 4.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 2.0 + open_bins_count as f64 * 0.5;
    }

    // Slight global pressure toward consolidating residual mass.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward bins that leave room for the next item (tight fit bonus).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.5 + 0.18 * (1.0 - slack / cap).min(1.0));
    }

    // Penalize near-miss residuals that block the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Penalize tiny dead-space residuals (wasted slivers).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.75;
    }

    // Mild bonus for bins with above-average fill (compaction direction).
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // When many bins can fit the item, prefer the one with the least post-residual;
    // when only one fitting bin exists, be more forgiving to avoid opening new bins.
    if fitting_bins_count > 1 {
        score -= 0.10 * (1.0 - post_residual as f64 / cap);
    } else if fitting_bins_count == 1 {
        score -= 0.20;
    }

    // Lookahead: if the next item is large and this bin's post-residual is a poor
    // match for it, slightly discourage using this bin so larger bins stay flexible.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size - post_residual) as f64 / cap;
        score += waste_ratio * cap * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item exactly fits the post-residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Penalize if next item fits with a large gap left over (double dead space).
    if next_item_size > 0 && next_item_size < post_residual {
        let gap_after_next = post_residual - next_item_size;
        score += 0.5 * gap_after_next as f64;
        // But reward chainable placements somewhat.
        score -= 0.3 * next_item_size as f64;
    }
    // Penalize if next item cannot use the residual at all (dead space).
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.8 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it
    // attractive only when the item is large (little residual wasted) or
    // existing fits are all poor.
    if bin_residual == bin_capacity {
        score += 250.0; // base cost of opening a new bin
        // Large items waste little space in a fresh bin.
        score -= 2.0 * item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // If many bins are open and average residual is large, discourage new bin.
        score += 0.5 * mean_residual;
    }

    // Small penalty for tiny unusable residuals (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
