    // Lookahead: reward bins that can still host the next item, weighted by how snugly it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let snug = 1.0 - (slack / cap).min(1.0);
        score -= next_item_size as f64 * (0.5 + 0.18 * snug);
        // Extra reward when this is one of few fitting options: keep scarce capacity alive.
        if fitting_bins_count <= 2 {
            score -= next_item_size as f64 * 0.25;
        }
    }

    // Penalize near-miss residuals that block the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Penalize tiny stranded residuals more aggressively.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.8;
    }

    // Mild deviation term: prefer bins whose residual is typical, avoid outliers.
    score -= 0.06 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Prefer opening a new bin only when no open bin offers a decent fit:
    // make the new-bin candidate (full residual) less attractive when tight fits exist.
    if bin_residual == bin_capacity && fitting_bins_count > 0 && next_item_size > 0 {
        let best_gap = post_residual.saturating_sub(next_item_size);
        if best_gap <= bin_capacity / 8 {
            score += cap * 0.10;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: subtract a bonus proportional to how snugly the item fits.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space: small post_residuals that no item can usefully fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item could exactly fill the remaining space,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // post_residual can still host the next item: mild reward.
        score -= 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot fit here afterwards: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It should only win when the item leaves a very large residual there
    // relative to alternatives, or when no open bin fits well.
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with tight fits win first.
        score += 10.0;
        // But early in the stream, opening bins is cheap and useful.
        score -= 15.0 * (1.0 - progress);
    }

    // Global state coupling: when open bins are collectively full (low mean
    // residual), opening a new bin is more acceptable.
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 20.0 * mean_tightness;
    } else {
        // Prefer bins that are tighter than the average open bin.
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    // Late in the stream, be extra conservative with new bins.
    if bin_residual == bin_capacity {
        score += 30.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose post-residual can host the next item,
    // scaled by how snugly the next item fits (tighter = better).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let snug = (1.0 - slack / cap).min(1.0);
        score -= next_item_size as f64 * (0.5 + 0.18 * snug);
    }

    // Penalize near-miss residuals that strand almost-enough space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        let miss_ratio = miss / next_item_size as f64;
        score += miss * (0.3 + 0.25 * miss_ratio);
    }

    // Dead-space penalty for tiny unusable residuals.
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (cap / 10.0 - post_residual as f64) * 0.75;
    }

    // Mild deviation term from the mean residual landscape.
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Scarcity coupling: when few bins can fit the current item, prefer
    // consuming one of them rather than fragmenting; also make the fresh-bin
    // candidate less attractive unless it is genuinely needed.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (fitting_bins_count as f64);
        score -= 2.0 * scarcity * (post_residual as f64 / cap);
    }

    // When many bins are open, slightly discourage opening yet another one.
    if bin_residual == bin_capacity && open_bins_count > 2 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let r = post_residual as f64;

    // Dead-space avoidance: tiny gaps are nearly useless, scaled harder.
    if post_residual > 0 {
        if r < 8.0 {
            score += 0.8 * (cap / 8.0 - r).max(0.0) + 35.0 * (8.0 - r);
        } else if r <= 22.0 {
            score += 1.0 * (22.0 - r);
        } else if r <= 40.0 {
            score -= 0.2 * (r - 22.0);
        } else {
            score -= 0.45 * (r - 40.0);
        }
    } else {
        score -= 35.0; // perfect fit
    }

    // Tightness reward: filling most of the bin's space is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead synergy: strong reward when next item consumes the leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.55 + 0.2 * (1.0 - slack / cap).min(1.0));
        if slack < 8.0 {
            score -= 15.0;
        }
    }
    // Penalize when next item cannot use a mid-sized leftover.
    if next_item_size > post_residual && post_residual > 0 {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: fewer new bins when crowded, relaxed late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).powf(1.25) * (1.0 - 0.45 * progress);
    score += 0.18 * pressure;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: costly unless crowded or next item is large.
    if bin_residual == bin_capacity {
        score += 28.0;
        score -= 0.4 * open_bins_count as f64;
        if next_item_size > 0 {
            score -= 0.3 * next_item_size as f64;
        }
        score -= 0.45 * fill_ratio * cap;
    }

    // Residual-balance term: prefer bins near the fleet mean, keeping gaps usable.
    score -= 0.06 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap; // how full the bin becomes
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear reward for tight fits (post_residual small relative to capacity)
    score -= 30.0 * tightness * tightness;

    // Smooth interaction: tight fits become more valuable as stream progresses
    score -= 20.0 * tightness * tightness * tightness * progress;

    // Penalize large dead space non-linearly, amplified late in the stream
    let waste_frac = pr / cap;
    score += 15.0 * waste_frac * waste_frac * (0.5 + progress);

    // Reward bins whose residual is close to the next item (smooth coupling)
    if next_item_size > 0 && pr >= next_item_size {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // next item cannot fit here; mild penalty growing with shortfall
        let shortfall = (next_item_size as f64 - pr) / cap;
        score += 8.0 * shortfall * shortfall;
    }

    // Last-chance bonus when few bins fit the item
    if fitting_bins_count <= 1 {
        score -= 12.0;
    } else {
        // mild crowding penalty when many alternatives exist
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Coupling with mean residual: prefer bins deviating from the mean
    // (keeping residual diversity), smooth quadratic term
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for consolidating into fewer bins as stream progresses
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate handling: only attractive early or for large items
    if bin_residual == bin_capacity {
        let early_bonus = 10.0 * (1.0 - progress);
        let size_pull = 12.0 * norm_item;
        score = score - early_bonus - size_pull + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let pr_norm = pr / cap;

    // Core: prefer minimal post-residual, stronger weight later in the stream
    let mut score = pr * (0.9 + 0.5 * progress);

    // Reward tight fits: near-perfect fills get a strong bonus
    if pr > 0.0 && pr <= (item_size as f64) / 6.0 {
        score -= 3.0;
    }

    // Lookahead: reward leaving room for the next item, penalize near-misses
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) as f64;
            score -= ni * (0.5 + 0.15 * (1.0 - (slack / cap).min(1.0)));
            // Bonus if the bin can host the next item twice (chained lookahead)
            if pr >= 2.0 * ni {
                score -= 1.5;
            }
        } else if pr > 0.0 {
            // Penalize residuals that cannot host the next item, proportional to near-miss
            score += (ni - pr) * (0.3 + 0.4 * progress);
        }
    }

    // Penalize dead slivers unlikely to host typical items
    if pr > 0.0 && pr < cap / 10.0 {
        score += (cap / 10.0 - pr) * 0.9;
    }

    // Prefer bins whose residual is close to the item (best-fit behavior)
    score -= (br - item_size as f64).abs().recip() * 10.0 * cap / (cap + br);

    // Mild tie-break toward residuals near the running mean
    score -= 0.05 * (1.0 - ((br - mean_residual).abs() / cap).min(1.0));

    // Scarcity handling: when few bins fit, prefer existing bins strongly
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - 0.5 * progress);
    }

    // New-bin candidate handling: default penalty, relaxed under pressure
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).min(0.5);
        score += 2.0 + 1.5 * progress + 2.5 * pressure;
        // Allow a new bin if all open fits would leave bad slivers or no fits exist
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 3.0;
        }
        // Allow new bin when the best existing fit would strand a large dead space
        if next_item_size > 0 && pr > 0.0 && pr < (next_item_size as f64) * 0.5 && pr < cap / 10.0 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (1/4, 1/3, 1/2, full)
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Dead space: residuals that are too small to be useful get penalized
    // superlinearly, with modulo structure on the residual itself.
    let dead_threshold = cap / 10.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * 4.0;
    }
    if post == 0.0 {
        score -= 15.0; // perfect fit reward
    }

    // Harmonic class match: if next item fits exactly into post_residual,
    // strongly reward (chain of perfect fits).
    if nxt > 0.0 && post >= nxt {
        let slack = post - nxt;
        score -= 10.0 - slack.min(10.0) * 0.5;
    } else if nxt > 0.0 && post < nxt {
        // next item won't fit here; penalize small leftover less if it's a
        // "harmonic remainder" (divides capacity nicely)
        let r = post_residual;
        if r > 0 && bin_capacity % r == 0 {
            score -= 3.0; // e.g. residual 50, 25, 20 stays reusable
        } else if r < nxt * 0.5 {
            score += 4.0; // awkward remainder
        }
    }

    // Integer-division thresholds on post_residual (capacity eighths)
    let eighth = (post / (cap / 8.0)) as i64;
    score -= match eighth {
        0 => 0.0,
        1 => 1.0,
        2 => 2.0,
        3 => 3.5,
        4 => 5.0,
        _ => 6.0,
    } as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on
    // tiny items unless the fit is near-perfect.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_ratio = item / bin_residual.max(1) as f64;
        if fit_ratio < 0.5 {
            score += 8.0;
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin for large items or when open bins are fragmented,
        // penalize it for small items early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large = item >= cap * 0.5;
        if large {
            score -= 6.0;
        } else {
            score += 4.0 + 4.0 * (1.0 - progress);
        }
        // If many bins already fit the item, opening a new one is wasteful
        if fitting_bins_count > 2 {
            score += 6.0;
        }
        // Pair potential: new bin + next item harmonic pairing
        if nxt > 0.0 && cap >= item + nxt {
            let rem = cap - item - nxt;
            score -= (rem == 0.0) as i32 as f64 * 8.0;
            score -= (rem <= cap / 10.0) as i32 as f64 * 3.0;
        }
    }

    // Mean residual coupling: placing into a bin far from the mean residual
    // balances fragmentation; mildly favor bins below mean residual.
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    } else {
        score -= 0.5;
    }

    // Modulo-5 structure on post_residual: multiples of 5 are statistically
    // easier to fill in integer-size streams.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead reward: prefer bins where the next item also fits with tight slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= next_item_size as f64 * (0.55 + 0.2 * (1.0 - slack / cap).min(1.0));
    }

    // Penalize near-miss residuals that waste space for the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Penalize small dead-space residuals (wasted slivers), scaled by stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    if post_residual > 0 && post_residual < bin_capacity / 8 {
        score += (bin_capacity as f64 / 8.0 - post_residual as f64) * (0.5 + 0.4 * progress);
    }

    // Mild deviation term
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Reward bins that become exactly tight after placement (perfect fits)
    if post_residual == 0 {
        score -= item_size as f64 * 0.3;
    }

    // Prefer bins whose residual supports repeated placements of the item
    if item_size > 0 && bin_residual >= item_size {
        let reps = bin_residual / item_size;
        if reps >= 2 {
            score -= 0.3 * (reps.min(4) as f64);
        }
    }

    // When many bins can fit this item, favor the emptiest usable one
    if fitting_bins_count > 2 && bin_residual < bin_capacity {
        score += (fitting_bins_count as f64).ln().max(0.0) * 0.25 * (post_residual as f64 / cap);
    }

    // Early-stream balance bias, fading over time
    if progress < 0.25 {
        score += 0.5 * (1.0 - progress / 0.25) * ((bin_residual as f64 / cap) - 0.5).abs();
    }

    // Late-stream urgency: prefer near-full bins harder as stream ends
    if progress > 0.7 {
        score += 0.6 * ((progress - 0.7) / 0.3) * (bin_residual as f64 / cap);
    }

    // New-bin candidate: only open a fresh bin when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let best_possible = if item_size > 0 { (bin_capacity % item_size.max(1)) as f64 } else { cap };
        score = cap + best_possible * 0.5 + open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (1..=10 given the 1..100 interface) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 {
        // Usable gap: mild reward scaled by how well it could host future items.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let usable_bonus = if (next_item_size as u32) <= post_residual && next_item_size > 0 {
            25.0
        } else {
            5.0
        };
        score -= usable_bonus * (1.0 + 0.5 * (1.0 - progress));
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: with many bins open, consolidate into existing bins
    // rather than spreading; penalize the new-bin candidate accordingly.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New empty bin: high base cost, reduced when item is large relative
        // to capacity (big items are hard to place later).
        score += 40.0 + 0.8 * pressure - 0.2 * item_size as f64;
    } else {
        // Existing bin: reward slightly with more open bins (consolidation).
        score -= 0.3 * pressure;
    }

    // Prefer bins tighter than the mean (leaving large-residual bins flexible).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // Next item won't fit here afterwards; small penalty if gap becomes dead.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Lookahead: reward bins that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        let tight = (1.0 - slack / cap).min(1.0);
        score -= next_item_size as f64 * (0.5 + 0.18 * tight);
    }

    // Penalize bins that would be left nearly useless for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.32;
    }

    // Strong penalty for tiny residual slivers (dead space ratio control).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += (bin_capacity as f64 / 10.0 - post_residual as f64) * 0.85;
    }

    // Mild penalty for very large leftover residual (wasted capacity).
    if post_residual > bin_capacity * 6 / 10 {
        score += 0.5;
    }

    // Deviation-from-mean term: prefer bins with residual close to the mean.
    score -= 0.06 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Congestion-aware tiebreak: when few bins fit, favor tighter fits more.
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score -= 0.10 * scarcity * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of next item into post_residual is gold.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + 40.0 * (1.0 - slack / bin_capacity as f64);
