pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common item
    // sizes (10, 20, 25, 50) are more reusable -> reward them.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual % 10 == 0 {
        score -= 40.0;
    } else if post_residual % 5 == 0 {
        score -= 15.0;
    }

    // Integer-division dead-space classes: small odd remainders are hard to fill.
    let dead_class = post_residual / 10; // 0..9 usable space class
    score += (dead_class as f64) * 2.0;

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual && post_residual % next_item_size == 0 {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // Next item won't fit here: penalize leaving large unusable chunks
            // less if post residual is tiny (nearly full bin is fine).
            if post_residual < 10 {
                score -= 20.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when any
    // open bin has a good harmonic fit. Make the empty bin score moderately
    // high unless the stream is early or the fit here is terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 100.0 * progress;
        // Allow new bins when open bins are very full on average.
        if mean_residual < 15.0 {
            score -= 180.0;
        }
    }

    // Prefer fuller bins (smaller residual) overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 20.0;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer exact-capacity-fraction placements: item_size dividing capacity
    // leaves harmonically aligned residuals.
    if item_size > 0 && bin_capacity % item_size == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the smallest
    // possible item (1..=100 range, but treat < 10 as likely dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Small unusable-ish gaps (cannot fit anything meaningful) get graded penalties.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Coupling with next item lookahead: reward leaving exactly enough room
    // for the next item (chained packing), penalize near-misses that strand space.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if gap < 1.0 {
            score -= 250.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            score -= 40.0 - gap.min(40.0);
        } else {
            // next item won't fit here; the residual becomes dead space unless tiny
            score += gap.min(60.0) * 3.0;
        }
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open
    // bins, filling existing bins is cheap so slight reward.
    let obp = open_bins_count as f64;
    score += (obp - 2.0).max(0.0) * 6.0;

    // Prefer bins tighter than the mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild progression term: later in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // New-bin candidate: an empty bin has full residual; make it attractive only
    // when this would otherwise be a poor fit. Baseline penalty keeps it behind
    // good fits but ahead of dead-space-creating placements.
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize any wasted space relative to the mean residual of open bins.
    if (post_residual as f64) > mean_residual {
        score += 0.6 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
