    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: item + next item exactly fills the bin.
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: good, but less perfect the larger the leftover gap.
            score -= 25.0 - 0.25 * ((post_residual - next_item_size) as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to the shortfall.
            score += 0.5 * ((next_item_size - post_residual) as f64);
