        // Last item: prefer tightest possible fit.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mild pressure to close out nearly-full bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    // Discard opening a new bin unless existing fits are clearly poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size.min(bin_capacity) {
            // A fresh bin can still accommodate the next item too: soften the penalty.
            score -= 8.0;
        }
