    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 0.3 * progress);

    // Strong near-perfect fill reward
    if pr == 0.0 {
        score -= 30.0;
    } else if pr <= (item_size as f64) / 8.0 {
        score -= 9.0;
    }

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) as f64;
            score -= 32.0 + 45.0 * (1.0 - slack / cap);
            if pr == ni {
                score -= 30.0;
            }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 14.0 * (after_next / cap);
            } else if after_next >= ni {
                score -= 10.0;
            }
        } else {
            // Penalize near-miss residuals that cannot host next item
            score += 10.0 * (pr / cap);
            let miss = (ni - pr) as f64;
            if miss < 22.0 {
                score += 0.45 * miss;
            }
        }
    }

    // Penalize dead slivers unlikely to host typical items
    let dead = pr / cap;
    if dead > 0.0 && dead < 0.12 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 8.5 * (1.0 - dead / 0.12);
    }

    // Unique-fit preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 24.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.4 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.55 {
            score -= base + 15.0 * (1.0 - 2.0 * progress);
        } else {
            score += base;
            score += 0.6 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 3.0;
        }
        if progress > 0.7 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 3.5;
        }
    }

    // Tightness bonus (sharpened: quadratic + small cubic tail to favor very tight fits)
    let tight = 1.0 - pr / cap;
    score -= 5.0 * tight * tight + 2.0 * tight * tight * tight;

    // Mild tie-break toward bins with residual close to the running mean
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // New: reward bins whose residual is a near-exact multiple match for the next item
    // (anticipates chaining two future items into the leftover space)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let two = 2.0 * ni;
        if pr >= two && pr < two + ni {
            score -= 6.0 * (1.0 - (pr - two) / ni.max(1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = 1.0 + progress * (2.0 * pr_norm) + progress * progress * (3.0 * pr_norm * pr_norm);
    score *= poly;

    // Reward tight fits (small post_residual) increasingly as stream progresses
    score -= progress * (cap - pr) * 0.5;

    // Penalize post_residual close to half-capacity (unusable dead space) via smooth quadratic
    let half = 0.5;
    let dead = pr_norm - half;
    score += 6.0 * dead * dead * cap * (0.5 + progress);

    // Last-chance bonus: strongly favor this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 5.0 * (1.0 - pr_norm) * (0.5 + progress);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure toward consolidation when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 2.0;

    // Mean-residual deviation coupling
    score += (pr - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "useful"
    // classes (multiples of small denominators) are rewarded.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect closure
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr <= 9 {
        12.0 // dead space: too small for min item
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead coupling: reward residuals that can host the next item exactly,
    // penalize residuals just barely above/below next_item_size.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (pr as f64) == n {
            score -= 15.0;
        } else if pr as u32 >= next_item_size {
            let slack = pr as f64 - n;
            score -= 6.0 * (1.0 - slack / cap_f);
        } else {
            let gap = n - pr as f64;
            score += 4.0 * (gap / cap_f);
        }
    }

    // Integer-division threshold on post_residual: classify usable zones.
    let zone = pr / 25; // 0..=4 harmonic zone
    score -= match zone {
        0 => 6.0,       // very tight fill (0..25): mostly good unless dead
        1 => 2.0,
        2 => 0.0,
        3 => -1.5,
        _ => -3.0,      // roomy bin: keep flexible bins attractive
    };

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.05 * (bin_residual as f64);
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: only attractive when existing bins would waste a lot.
    if bin_residual == bin_capacity {
        let waste = if post_residual == 0 { 0.0 } else { mean_residual };
        score += 18.0 - 0.5 * waste;
        // Late in the stream, discourage opening bins (less time to amortize).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is small, a fresh bin is fine; if huge, prefer fresh bin.
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / cap_f;
    score -= 5.0 * fill * fill;

    // Mild dispersion penalty: avoid scattering across many similar bins.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..10)
    // are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    }
    // Gap that cannot fit the lookahead item is likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }
    // Reward fits that leave room exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // so penalize opening a new empty bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 40.0 + 8.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: bins with residual far below the mean are tight;
    // filling them fully is good, leaving them near-empty is wasteful.
    let res = bin_residual as f64;
    if res + 0.5 < mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    // Early in the stream, be slightly more willing to open bins (spread items);
    // late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching:
    // Strongly reward exact or near-exact match of post_residual with next_item_size.
    let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chain: item leaves exactly the space the next item needs.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward closeness of the match.
            score -= 30.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit in the leftover: penalize dead space,
            // scaled by how badly the chain breaks.
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: only compactness matters.
        score -= 10.0;
    }

    // Penalize leftovers that are too small for any plausible item (dead space),
    // with a tuned "waste band" around small residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Relative-to-mean coupling: prefer bins whose resulting residual stays
    // close to the fleet mean (balanced packing), unless it's a perfect match.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild encouragement to fill nearly-full bins (low post_residual).
    score += 0.05 * (bin_capacity as f64 - post_residual as f64).recip().max(0.0) * 10.0;

    // Late in the stream, be slightly more conservative about opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            // New-bin candidate: penalize more as the stream progresses,
            // unless the current item leaves a perfect lookahead match.
            let mut new_bin_penalty = 12.0 + 18.0 * progress;
            if next_item_size > 0 && post_residual == next_item_size {
                new_bin_penalty -= 20.0;
            }
            score += new_bin_penalty;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
