pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / (bin_capacity as f64);
    score += fit_ratio * 20.0;

    // Penalize bins whose residual was already small (precious space) unless it's a perfect fit.
    if post_residual > 0 {
        score += (bin_residual as f64).ln() * 2.0;
    } else {
        score -= 50.0; // perfect fit bonus
    }

    // Last-chance bin: strong reward to use it and avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; penalize leaving awkward small leftovers
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // Last item in stream: just minimize post residual.
        score -= 5.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_tight = mean_residual / bin_capacity as f64;
        // Open a new bin when existing residuals are small and no other bin fits well.
        score = 120.0
            - poor_fits * 70.0
            - (1.0 - mean_tight) * 30.0
            - progress * 20.0
            + (post_residual as f64) * 0.5;
        if fitting_bins_count == 1 {
            score += 80.0; // don't open new bin when exactly one bin fits
        }
    }

    // Mild penalty on bin proliferation: encourage consolidating into existing bins.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be more aggressive about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits, scaled by capacity
    let mut score = pr / cap;

    // Smooth non-linear coupling: post_residual polynomial interacting with progress.
    // Early in the stream, small residuals matter less; later, dead space is heavily penalized.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 + 3.0 * progress) + pr_norm * pr_norm * pr_norm * (2.0 + 4.0 * progress);
    score += poly;

    // Reward near-perfect fits more strongly as stream progresses (smooth exponential-ish via polynomial)
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (0.5 + 1.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 1.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.25 * (next_item_size as f64 / cap);
    }

    // Slight preference to fill bins with many others (consolidation) via mean residual coupling
    let mean_norm = mean_residual / cap;
    score += 0.3 * mean_norm * mean_norm * (1.0 - progress);

    // Penalize opening new bins early (new-bin candidate gets a progress-dependent penalty)
    if bin_residual == bin_capacity {
        score += 0.5 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Classes: 0 (perfect fit), small dead space, medium, large.
    let cap_frac = bin_capacity / 4; // 25-unit quarters
    let post = post_residual as i64;

    // Perfect fit: strong reward.
    if post == 0 {
        score -= 500.0;
    } else if post <= 5 {
        // Nearly perfect: tiny residual is fine.
        score -= 60.0;
    } else if post < cap_frac {
        // Small dead space class (1..24): mildly acceptable.
        score -= 20.0;
    } else if post == cap_frac {
        // Residual exactly one quarter: reusable class (fits items <= 25).
        score -= 35.0;
    } else if post < 2 * cap_frac {
        // Quarter..half: dead-space risk grows.
        score += 10.0;
    } else if post == 2 * cap_frac {
        // Half residual: highly reusable class.
        score -= 45.0;
    } else if post < 3 * cap_frac {
        score += 5.0;
    } else {
        // Large residual: bin barely touched; penalize relative to reuse.
        score -= 10.0;
    }

    // Harmonic coupling with next_item_size: does the post residual
    // form a good class for the upcoming item?
    if next_item_size > 0 {
        if post >= next_item_size as i64 {
            let slack = post - next_item_size as i64;
            match slack {
                0 => score -= 120.0,           // next item fits perfectly after
                1..=5 => score -= 70.0,
                _ if slack < cap_frac as i64 => score -= 25.0,
                _ => score += 5.0,
            }
        } else {
            // Next item cannot use this bin's residual: dead-space penalty.
            score += 25.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer tighter bins generally (residual close to item size).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Early in stream: keep bins open loosely (favor consolidating into
    // existing bins less aggressively); later: pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 40.0 * progress * (1.0 - tightness.max(0.0));

    // Many open bins: encourage filling them rather than opening new ones.
    score += (open_bins_count as f64).sqrt() * 3.0;

    // Mean residual alignment: bins below mean residual are "fuller" — prefer them.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when open bins score badly.
        score += 80.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // stacking similar/large items in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
