            2 => { score += 15.0; }          // 20-29: awkward mid class
            3 => { score += 5.0; }           // 30-39: still restrictive
            4 | 5 => { score -= 10.0; }      // 40-59: flexible half-bin class
            _ => { score -= 20.0; }          // 60+: plenty of room remains
