    // New-bin candidate: penalize opening a new bin mildly, more so when
    // decent fitting bins exist; encourage it only when residuals are low.
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / open_bins_count.max(1) as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 0.3 * avg_fit - 20.0 * progress;
        if item_size > half {
            score -= 10.0; // big items are fine in a fresh bin
        }
    }

    // Mild preference for filling bins that are already relatively full.
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 8.0;

    score
}

