    // average is wasteful; less than average is efficient consolidation.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a good fit
    // (large item relative to residuals, or post_residual would be dead space).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
