    if next_item_size > 0 && pr > 0.0 && pr == (bin_residual as f64 - item_size as f64) {
        score -= 6.0;
    }

    // Two-item lookahead — reward residuals that can host next two items
    if next_item_size > 0 && pr >= 2.0 * next_item_size as f64 {
        score -= 5.0 * (1.0 - progress);
    }

    // Discourage leaving residual just below the mean residual (hard-to-fill gap)
    if pr > 0.0 && pr < mean_residual * 0.9 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0;
    }

