    // --- Harmonic class of the leftover space ---
    // Classify post_residual into residue classes modulo 10 and modulo 20:
    // leftovers that are multiples of 10/20 are "harmonic" and more reusable.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;
    let next = next_item_size as i64;

    // Reward post-residuals that are exact multiples of 10 (harmonic with the
    // typical item granularity): subtract a bonus proportional to the class.
    let mod10 = post % 10;
    let mod20 = post % 20;
