        score -= 6.0;
        if mod20 == 0 { score -= 4.0; }
        if post % 40 == 0 { score -= 2.0; }
    } else {
        // Penalize awkward leftovers: small non-harmonic slivers are dead space.
        if post > 0 && post < 10 { score += 14.0; }
        // Odd residues between classes are mildly bad.
        score += (mod10 as f64) * 0.5;
    }

    // --- Integer-division threshold on post_residual ---
    // How many "average" future items could still fit?
    let avg_item = 40.0f64;
    let future_slots = (post as f64 / avg_item).floor();
    score -= future_slots * 3.0;

    // --- Lookahead coupling (k=2) ---
    if next > 0 {
        if next <= post {
            // The next item fits here after this placement: strong reward.
            score -= 12.0;
            // Extra reward if the pair leaves a harmonic remainder.
            let after2 = post - next;
            if after2 % 10 == 0 { score -= 6.0; }
            if after2 == 0 { score -= 10.0; }
            // Reward tight two-item packing: post_residual just above next.
            if post - next < 10 { score -= 4.0; }
        } else {
            // Next item won't fit here: penalize proportionally to the gap,
            // but less if the leftover is still large enough to matter later.
            let gap = (next - post) as f64;
            score += gap * 0.15;
            if post < 20 { score += 8.0; } // this bin becomes nearly dead
        }
    } else {
        // Last item: prefer exact fill above all.
        if post == 0 { score -= 100.0; }
    }

    // --- Perfect fit dominates ---
    if post == 0 {
        score -= 50.0;
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Only this open bin can take the item; avoid opening a new bin
        // unless the fit is terrible.
        score -= 10.0;
        if post < 5 { score -= 5.0; }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are crowded
        // (low mean residual) or many bins are already open and fragmented.
        let crowded = mean_residual < 25.0;
        let fragmented = open_bins_count > 12;
        if crowded || fragmented {
            score -= 8.0;
        } else {
            score += 15.0;
        }
        // Early in the stream, opening fresh bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.25 { score -= 3.0; }
        // Never open a new bin for a tiny item.
        if item_size < 20 { score += 10.0; }
    }

    // --- Mean-residual context: prefer bins far from the mean when the mean
    // is large (consolidate big holes), prefer near-mean bins when mean is small.
    let dev = (bin_residual as f64 - mean_residual).abs();
    if mean_residual > 50.0 {
        score -= dev * 0.1;
    } else {
        score += dev * 0.05;
    }

    // --- Slight preference for tighter fits as the stream matures ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - post_residual) as f64 * 0.02;

    score
}

