    score -= fill_ratio * 8.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit in post_residual but would fit a fresh bin, penalize leaving a big gap.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += (post_residual as f64) * 0.15;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Prefer bins with below-mean residual (tighter bins fill first).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 10.0;

    score
}

