        score -= 5.0 * tightness;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more conservative (favor spreading),
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> discourage opening new bins,
    // encourage consolidating into existing ones.
    if bin_residual != bin_capacity {
        score -= 0.05 * (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
    } else {
        // New-bin candidate: penalize when existing bins are spacious and numerous,
        // reward when open bins are nearly full (mean residual small).
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score += 6.0 * avg_fill * (open_bins_count as f64).ln().max(0.0);
        // A new bin is attractive if the item is large and post residual stays useful.
        score -= 0.03 * post_residual as f64;
    }

    // Slight preference for bins whose residual is close to item size (near-perfect fit).
    let fit_gap = (bin_residual - item_size) as f64;
    score -= 4.0 * (1.0 - fit_gap / bin_capacity as f64) * (1.0 - fit_gap / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr * (1.0 + 0.3 * progress);

    // Strong near-perfect fill reward
    if pr == 0.0 {
        score -= 30.0;
    } else if pr <= (item_size as f64) / 8.0 {
        score -= 9.0;
    }

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) as f64;
            score -= 30.0 + 42.0 * (1.0 - slack / cap);
            if pr == ni {
                score -= 30.0;
            }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 13.0 * (after_next / cap);
            } else if after_next >= ni {
                score -= 10.0;
            }
        } else {
            // Penalize near-miss residuals that cannot host next item
            score += 10.0 * (pr / cap);
            let miss = (ni - pr) as f64;
            if miss < 22.0 {
                score += 0.45 * miss;
            }
        }
    }

    // Penalize dead slivers unlikely to host typical items
    let dead = pr_norm;
    if dead > 0.0 && dead < 0.11 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 8.5 * (1.0 - dead / 0.11);
    } else if dead > 0.11 && dead < 0.24 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0 * (1.0 - (dead - 0.11) / 0.13);
    }

    // Unique-fit preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 24.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.4 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.55 {
            score -= base + 14.0 * (1.0 - 2.0 * progress);
        } else {
            score += base;
            score += 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.5;
        }
        if progress > 0.7 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 6.0;
        }
    }

    // Tightness bonus
    let tight = 1.0 - pr_norm;
    score -= 4.0 * tight * tight;

    // Mild tie-break toward bins with residual close to the running mean
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
