    let mut score = post / cap;

    // Non-linear polynomial coupling: wasted space penalized quadratically,
    // amplified as the stream progresses.
    let waste = post / cap;
    score += (waste * waste) * (0.5 + 2.0 * progress);

    // Reward tight fits (small post residual) with a smooth cubic term.
    score -= (1.0 - waste).powi(3) * 0.8 * (1.0 - progress);

    // Last-chance bonus: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 {
