pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "capacity fraction band" it lands in.
    // Residuals in (0, 10] are dead space; residuals that can host the next item are gold.
    let can_host_next = next_item_size > 0 && post_residual >= next_item_size;
    let dead_space = post_residual < 10;

    // Reward placements whose post-residual is a "harmonic" residue: divisible-friendly
    // chunks (multiples of 10 or 20) are more reusable by future items.
    let harmonic = post_residual % 10 == 0 && post_residual > 0;
    let semi_harmonic = post_residual % 5 == 0 && post_residual > 0;

    if can_host_next {
        // Exact fit for the lookahead item is the dream: subtract heavily.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + 0.5 * next_item_size as f64;
        score -= 15.0 * (-slack / 25.0).exp(); // tighter fit for next item -> better
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for the next item: penalize by how "wasted" it is,
        // scaled by the fraction of the stream already consumed.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * progress;
    }

    if dead_space {
        score += 12.0; // unusable sliver
    }
    if harmonic {
        score -= 6.0;
    } else if semi_harmonic {
        score -= 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish score anchored at capacity, but discourage
    // opening new bins when mean residual across open bins is still healthy.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 + mean_residual * 0.6 - 5.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    }

    // Slight preference for filling fuller bins (lower residual first).
    score += 0.15 * (bin_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: residuals >= half capacity are still valuable,
    // so mildly discourage dumping large items into them unless tight fit.
    if post_residual >= bin_capacity / 2 && !can_host_next {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (wasted capacity).
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Perfect or near-perfect fit is excellent: strongly reward.
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // Awkward small gap: penalize hard.
        score += 35.0;
    }

    // Reward exact fills completely (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current bin would leave a large awkward gap or the fit is poor.
    if bin_residual == bin_capacity {
        // Brand-new bin: baseline cost of consuming fresh capacity.
        score += 20.0;
        // Attractive if the item is large relative to capacity (efficient use
        // of fresh space) and few bins are open.
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * size_frac;
        // Open-bin pressure: many open bins => discourage new bins.
        score += 3.0 * open_bins_count as f64;
        // If the item would leave a tiny unusable gap in a fresh bin, that's
        // actually fine (near-perfect fresh fill) — handled by size_frac.
        // If next item is large and won't fit the fresh residual, penalize.
        if next_item_size > post_residual && next_item_size > 0 {
            score += 10.0;
        }
    } else {
        // Existing bin: mild reward proportional to how well the item fills it.
        let fill_frac = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_frac;
        // Penalize placing into a bin whose residual is much larger than the
        // item when other bins could take it (wasteful fragmentation).
        if fitting_bins_count > 1 && (post_residual as f64) > mean_residual {
            score += 8.0;
        }
        // Lookahead: if the post residual exactly accommodates the next item,
        // this is a great chaining placement.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            // Post residual can't host next item: mild penalty scaled by gap.
            score += 5.0 * ((post_residual as f64) / bin_capacity as f64);
        }
        // Progress-based pressure: late in the stream, prefer tight packing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress * ((post_residual as f64) / bin_capacity as f64);
    }

    score
}

