            score += 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.5;
        }
        if progress > 0.7 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 6.0;
        }
    }

    // Tightness bonus
    let tight = 1.0 - pr_norm;
    score -= 4.0 * tight * tight;

    // Mild tie-break toward bins with residual close to the running mean
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    // Prefer bins whose residual matches the next item exactly after placement chains
    if next_item_size > 0 && pr > 0.0 && pr == (bin_residual as f64 - item_size as f64) {
        score -= 6.0;
    }

    // Two-item lookahead — reward residuals that can host next two items
    if next_item_size > 0 && pr >= 2.0 * next_item_size as f64 {
        score -= 5.0 * (1.0 - progress);
    }

    // Discourage leaving residual just below the mean residual (hard-to-fill gap)
    if pr > 0.0 && pr < mean_residual * 0.9 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0;
    }

    // Exact-fit chain reward — residual after placement equals a plausible next item size
    if pr > 0.0 && next_item_size > 0 && (pr as u32) <= 100 && (pr as u32) >= item_size.min(next_item_size) / 2 {
        score -= 2.0 * (1.0 - progress);
    }

    // Reward bins whose residual is an exact multiple of the next item (chainability)
    if next_item_size > 1 && bin_residual >= next_item_size && (bin_residual % next_item_size) == 0 {
        score -= 1.5 + 2.5 * (1.0 - progress);
    }

    // Penalize residuals that are awkward sizes (prime-ish gaps) that waste space
    if pr > 0.0 && pr < 20.0 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 2.0 * (1.0 - pr / 20.0);
    }

    // New: pair-completion lookahead — strongly prefer bins whose residual exactly
    // equals item + next item (perfect two-item fill) or that leave exactly the next item
    if next_item_size > 0 {
        let pair = item_size as f64 + next_item_size as f64;
        if (bin_residual as f64 - pair).abs() < 0.5 {
            score -= 8.0 + 6.0 * (1.0 - progress);
        }
    }

    // New: scale unique-fit bonus by scarcity of fitting bins early in the stream
    if fitting_bins_count == 2 && progress < 0.5 && bin_residual < bin_capacity {
        score -= 4.0 * (1.0 - progress);
    }

    // New: discourage opening a new bin when any open bin would leave a residual
    // the next item could still use (protect reusable space)
    if bin_residual == bin_capacity && next_item_size > 0 && fitting_bins_count > 0 {
        let ni = next_item_size as f64;
        if pr >= ni && pr < ni * 2.5 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly scaled
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress: later, prefer tighter fits more
    let progress_coupling = progress * (2.0 * norm_pr - norm_pr * norm_pr);
    score += 40.0 * progress_coupling;

    // Penalize dead space relative to mean residual (smooth interaction)
    score += 10.0 * (norm_pr - mean_residual / cap).abs();

    // Last-chance bin reward: subtract to favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    }

    // Slight penalty for many open bins relative to progress (encourage consolidation later)
    score += 2.0 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod small divisors
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit bonus: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class-1: multiples of 5 and 10 are "friendly" gaps
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        }
        // Class-2: awkward gaps (mod 7, mod 3 residues) penalized
        if post_residual % 7 == 1 || post_residual % 7 == 3 {
            score += 3.0;
        }
        if post_residual % 3 == 2 {
            score += 2.0;
        }
        // Dead-space threshold via integer division: tiny gap is wasted
        let dead = post_residual / 10; // number of full 10-slots wasted
        if dead == 0 {
            score += 12.0; // gap < 10: unusable for any item
        }
        // Fractional capacity coupling
        let frac = pr / c;
        if frac < 0.05 {
            score += 10.0;
        } else if frac > 0.4 {
            score -= 5.0; // roomy leftover is flexible
        }
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item divides into gap nicely
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 7.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: keep it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / c;
        score = 45.0 + (1.0 - crowding) * 25.0 - (open_bins_count as f64).min(20.0);
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 10.0;
        }
    }

    // Slight progression drift: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are worthless dead space -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that can still fit the lookahead item (chainability).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            // gap too small for the next item: mild dead-space penalty
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins,
    // but keep the empty new-bin candidate neutral-to-slightly-penalized
    // so it only wins when fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Relative tightness: prefer bins whose remaining space after placement
    // is small compared to the mean residual of open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

