pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match: strong reward; decay quadratically with slack.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64).powi(2);
        // Extra bonus for near-exact match (slack <= 5).
        if slack <= 5.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to how far off the match is.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Penalize post_residual below the minimum item size (1) => dead space.
    if post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Reward relative to mean residual: bins tighter than average are preferred.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: only this bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Slight preference to fill nearly-full bins early vs late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Make brand-new empty bin less attractive unless current bins give bad fits.
    if bin_residual == bin_capacity {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = pr;

    // Strong lookahead: reward fits that leave room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) as f64;
            score -= 30.0 + 42.0 * (1.0 - slack / cap);
            if pr == ni {
                score -= 27.0; // perfect two-item fill
            }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 13.0 * (after_next / cap); // creates a dead sliver
            } else if after_next >= next_item_size.max(1) as f64 {
                score -= 9.0 + 4.0 * (after_next / cap); // can host next item again
            }
        } else {
            score += 9.0 * (pr / cap);
        }
    }

    // Only fitting bin: strong preference to keep it usable
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Dead-space penalties, graded by residual band
    let dead = pr / cap;
    if dead > 0.0 && dead < 0.11 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 7.5 * (1.0 - dead / 0.11);
    } else if dead > 0.11 && dead < 0.24 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0 * (1.0 - (dead - 0.11) / 0.13);
    }

    // New-bin candidate handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.4 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.55 {
            score -= base + 14.0 * (1.0 - 2.0 * progress);
        } else {
            score += base;
            score += 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.5;
        }
        if progress > 0.7 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 6.0;
        }
    }

    // General tightness reward
    let tight = 1.0 - (pr / cap);
    score -= 4.0 * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize new-bin candidate unless item is large and would leave a usable residual.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let penalty = 60.0 * (1.0 - tightness);
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual {
            -25.0
        } else {
            0.0
        };
        score += penalty + lookahead_bonus;
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing typical can use (post_residual < 10).
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0; // residual still usable by mid-size items
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 20.0 * chain;
    } else if next_item_size > post_residual {
        score += 6.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0;
    }

    // Time horizon: early in stream, be more selective (penalize waste); late, just fit anywhere.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 * 0.15);

    // Prefer bins whose residual is close to the item (best-fit coupling).
    score += (bin_residual - item_size) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    // Late in the stream, tight fits (small post_residual) matter more,
    // so the score grows super-linearly in pr_norm as progress -> 1.
    let warp = 1.0 + 2.0 * progress * progress;
    let mut score = pr * warp;

    // Smooth polynomial coupling: penalize mid-range dead space quadratically,
    // with strength increasing as the stream progresses.
    let dead = pr_norm * (1.0 - pr_norm); // peaks at pr_norm = 0.5
    score += 30.0 * progress * (dead * (1.0 - dead) * 4.0 - 0.5).abs();

    // Reward filling bins very snugly (near-zero residual), stronger late.
    score -= 15.0 * (1.0 - pr_norm).max(0.0) * (1.0 - pr_norm) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: prefer placements that still leave room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let after_next = (pr - nx) / cap;
            score -= 12.0 * (1.0 - (after_next - 0.5) * (after_next - 0.5) * 4.0) * (0.3 + progress);
        } else {
            score += 10.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for leaving residual far from mean residual (fragmentation).
    score += 0.15 * ((pr as f64) - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: penalize opening a bin early, less so late.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small to hold the smallest plausible item
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }

    // Harmonic class penalty: residuals in awkward zones (just above common sizes)
    // are fragile; residuals divisible into clean quarters are flexible.
    let pr = post_residual as i64;
    let awkward = |r: i64| -> f64 {
        // residual that is just barely above a typical item size is risky
        let mut pen = 0.0;
        for s in [10i64, 20, 25, 30, 40, 50, 60, 70, 80] {
            if r > s && r <= s + 5 {
                pen += (r - s) as f64 * 2.0;
            }
        }
        pen
    };
    score += awkward(pr);

    // Reward residuals that are multiples of 25 (harmonic quarters of capacity)
    if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead: penalize if the next item cannot fit in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item still fits here: mild reward, scaled by how snug
            score -= 5.0 + 10.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            // next item would be stranded if we burn this bin's space poorly
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Many open bins: encourage consolidation (prefer filling existing bins over new)
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).sqrt() * 2.0;
    }

    // Prefer bins tighter than the mean residual (good packing direction)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Early stream: keep bins open/flexible; late stream: pack aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.5 && post_residual > 0 {
        score += (1.0 - progress) * 6.0; // slight early penalty for low post-residual? no: reward low residual late
    } else if post_residual > 0 {
        score -= progress * 5.0;
    }

    // New-bin candidate must be strictly worse than decent fits
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
