            }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 13.0 * (after_next / cap);
            } else if after_next >= next_item_size.max(1) as f64 {
                score -= 9.0 + 4.0 * (after_next / cap);
            }
        } else {
            // Penalize near-miss residuals that cannot host next item
            score += 9.0 * (pr / cap);
            let miss = (ni - pr) as f64;
            if miss < 22.0 {
                score += 0.45 * miss;
            }
        }
    }

    // Penalize dead slivers unlikely to host typical items (two bands)
    let dead = pr_norm;
    if dead > 0.0 && dead < 0.11 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 8.5 * (1.0 - dead / 0.11);
    } else if dead >= 0.11 && dead < 0.24 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0 * (1.0 - (dead - 0.11) / 0.13);
    }

    // Unique-fit preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 24.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.35 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.6 {
            score -= base + 14.0 * (1.0 - 2.0 * progress);
        } else {
            score += base;
            score += 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 3.0;
        }
        if progress > 0.65 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 4.0;
        }
        // Perfect two-item packing into a fresh bin
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 6.0;
        }
    }

    // Tightness bonus
    let tight = 1.0 - pr_norm;
    score -= 4.0 * tight * tight;

    // Mild tie-break toward bins with residual close to the running mean
    score -= 0.05 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / cap).min(1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space pressure scales with how tight the fit is.
    let tightness = item_size as f64 / bin_capacity as f64;
    score += (post_residual as f64) * (1.0 - tightness) * 0.5;

    // Penalize bins whose residual cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward bins that can host both this item and the next.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones; with few open bins, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or item is small.
        score += 15.0 * pressure + (bin_capacity - item_size) as f64 * 0.3;
        // But if this is the only fitting option, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Last-chance bin: strong reward to fill it rather than open a new bin.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Reward using bins already below the mean residual (reduces fragmentation).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect 2-step match: item + next item fill the bin exactly.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits, penalize leftover gap after the lookahead pair.
            let gap = pr - nxt;
            score -= 25.0 - gap.min(40.0) * 0.45;
        } else {
            // Next item does not fit: penalize proportionally to how much it misses.
            let miss = nxt - pr;
            score += miss.min(80.0) * 0.35;
        }
        // Small nudge toward post_residual near the mean residual (keeps bins balanced).
        score += (pr - mean_residual).abs() * 0.05;
    } else {
        // Last item: just minimize post residual.
        score += 0.0;
    }

    // Penalize large dead space that likely becomes unusable (below typical item floor of 1..100).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 8.0; // tiny gap is fine, nearly full bin
    } else if pr >= 10.0 && pr < 25.0 {
        score += 3.0;
    } else if pr >= 25.0 {
        score += (pr - 25.0) * 0.30; // large residual wastes capacity
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a good fit (i.e., this bin is already empty) — otherwise discourage it.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No alternative: new bin is fine; give it a neutral-but-competitive score.
            score = (bin_capacity - item_size) as f64;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 20.0;
            }
        } else {
            // Open bins exist that fit; discourage opening a new one unless they fit badly.
            let worst_open = mean_residual.max(0.0);
            let slack = worst_open - item_size as f64;
            if slack < 12.0 {
                score = worst_open - item_size as f64 + pr * 0.5 - 10.0;
            } else {
                score = pr + 55.0;
            }
        }
    }

    // Slight stream-progression pressure: later in the stream, tighten bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead reward, scaled by how well it fits later.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty for wasting big residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        let mean_fit = (mean_residual - item_size as f64).max(0.0);
        // New bin is OK if existing residuals are poor or stream is late.
        let new_bin_penalty = 45.0
            - 0.4 * open_pressure
            - 20.0 * progress
            - 0.3 * mean_fit;
        score += new_bin_penalty.max(-10.0);
    } else {
        // Reward using bins whose residual is close to item (good fit ratio).
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 15.0 * fit_ratio;
        // Slight preference for bins with residual near mean (balance load).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Dead-space avoidance: residuals too small to ever fit typical items.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
