        }
        if progress > 0.7 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 6.0;
        }
    }

    // Tightness bonus
    let tight = 1.0 - (pr / cap);
    score -= 4.5 * tight * tight;

    // Chainability: residual that is an exact multiple of the next item supports repeated fills
    if next_item_size > 1 && bin_residual >= next_item_size && (bin_residual % next_item_size) == 0 {
        score -= 1.5 + 2.0 * (1.0 - progress);
    }

    // Reward residuals that can host the next two items (compaction lookahead)
    if next_item_size > 0 && pr >= 2.0 * next_item_size as f64 {
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize residuals just below mean residual (hard-to-fill gap)
    if pr > 0.0 && pr < mean_residual * 0.9 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0;
    }

    // Exact-fit chain reward: post residual is a plausible future item size
    if pr > 0.0 && next_item_size > 0 && (pr as u32) <= 100 && (pr as u32) >= item_size.min(next_item_size) / 2 {
        score -= 2.0 * (1.0 - progress);
    }

    // Penalize awkward tiny slivers that will almost surely waste space
    if pr > 0.0 && pr < 20.0 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 2.0 * (1.0 - pr / 20.0);
    }

    score
}

