pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0, 1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress:
    // early on, larger residuals are less penalized; late, tight packing matters more.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Polynomial weight: grows with progress, so residual is punished harder later.
    let w = 1.0 + 2.0 * progress * progress + 1.5 * progress;
    score += w * norm_pr * norm_pr * cap * 0.5;

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Lookahead coupling: penalize residuals that neither fit the next item well
    // nor leave a usable gap; smooth interaction with progress.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // next item fits: mild reward proportional to how well it fills remainder
            let fill = nx / pr.max(1.0);
            score -= 3.0 * fill * (0.5 + progress);
        } else {
            // next item won't fit here: penalize proportional to overshoot, smoothed
            let over = (nx - pr) / cap;
            score += 4.0 * over * over * cap * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Slight penalty proportional to open bin count relative to mean residual,
    // encouraging consolidation into bins with typical (large) residuals.
    score += 0.02 * (open_bins_count as f64) * (mean_residual - pr).abs() * 0.1;

    // New-bin candidate: penalize opening a fresh bin unless current fit is poor
    // (post_residual large) or late in the stream with many bins already open.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) / cap;
        score += 5.0 - 4.0 * poor_fit * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Penalize leftovers that fall in "dead zones" — too small for typical items.
    if post_residual > 0 {
        // Harmonic penalty: k * C / post_residual style coupling, inverted so
        // small post_residual (near-dead space) is heavily penalized.
        score += 30.0 / (post_f + 1.0);
        // Class boundaries at C/4, C/2, 3C/4: leftovers just below a boundary
        // are less useful than leftovers just above one.
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        let threeq = 3 * bin_capacity / 4;
        if post_residual <= quarter {
            score += 12.0 * (1.0 - post_f / (quarter as f64 + 1.0));
        } else if post_residual <= half {
            score -= 4.0 * ((post_residual - quarter) as f64 / (quarter as f64));
        } else if post_residual <= threeq {
            score -= 6.0 * ((post_residual - half) as f64 / (quarter as f64));
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Lookahead coupling: does the leftover accommodate the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nxt_f = next_item_size as f64;
            let nxt_frac = nxt_f / cap_f;
            // Reward if next item fills the leftover exactly (harmonic match).
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                let after = post_residual - next_item_size;
                // Reward closeness of next fit, penalize tiny second leftover.
                score -= 10.0 * (1.0 - after as f64 / (post_f + 1.0));
                if after > 0 && after < bin_capacity / 10 {
                    score += 6.0; // creates a new dead sliver
                }
                // Favor bins whose leftover is a harmonic multiple of next size class
                let class = (post_residual / next_item_size.max(1)) as f64;
                if class >= 2.0 && class <= 4.0 {
                    score -= 3.0 * class;
                }
                let _ = nxt_frac;
            }
        } else {
            // Next item won't fit here: leftover likely stranded unless stream ends.
            score += 8.0;
            // But if this is the last item, no future penalty applies.
            if step_index + 2 >= total_items {
                score -= 8.0;
            }
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or stream
    // pressure is high. Make empty-bin score moderate by default.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap_f * 0.6;
        // At stream start, opening bins is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins already open and mean residual is small, discourage.
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.2;
        // If item is large relative to capacity, a fresh bin is reasonable.
        score -= (item_size as f64 / cap_f) * 15.0;
        // If next item is large too, fresh bin keeps flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If no other bin can fit (fitting_bins_count counts only open bins that
        // fit; the new bin always fits), it will naturally win when desperate.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for tighter existing bins among equals (best-fit bias).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Mean-residual coupling: when average leftover is small, conserve capacity
    // by penalizing waste more strongly.
    score += (post_f - mean_residual).max(0.0) * 0.1;

    score
}

