    if next_item_size > 0 && pr > 0.0 && pr < next_item_size as f64 {
        let miss = 1.0 - pr / next_item_size as f64;
        score += 2.5 * miss * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class: classify post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize dead space that no plausible item (1..100) can use well.
    // Residuals in (0,10] are near-dead; residuals >= next_item_size are reusable.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            score -= 30.0; // next item can still use this bin
            // harmonic bonus: next item leaves another clean class
            let npr = post_residual - next_item_size;
            if npr == 0 {
                score -= 200.0;
            } else if npr >= 10 {
                score -= 15.0;
            } else {
                score += 25.0; // creates tiny dead space
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 20.0 + frac * 40.0;
        }
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of 10
    // are "harmonic" with typical item sizes
    if post_residual % 10 == 0 {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Integer division thresholds: classify residual size
    let cls = post_residual / 25; // 0..4
    match cls {
        0 => score += 35.0,          // tiny residual, mostly dead
        1 => score += 10.0,          // small
        2 => score -= 5.0,           // medium, useful
        _ => score -= 15.0,          // large residual, very reusable
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // would leave bad residuals; empty bin residual == capacity
    if bin_residual == bin_capacity {
        // fresh bin score: prefer it when current bin leaves a poor fit
        // baseline competitive score
        score = 0.5 * cap - 0.5 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if fitting_bins_count <= 1 {
            score += 120.0; // no real alternative: opening new bin is fine but don't beat last chance
        }
    }

    // Mild tie-break: prefer fuller bins overall (lower mean residual spread)
    score += 0.05 * (mean_residual - post_residual as f64);

    // Slight preference to consolidate early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

