            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize more if we wasted a lot of space
            score += 0.3 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for spreading across many fitting bins; prefer tightest
        score += 2.0 * (fitting_bins_count as f64).min(10.0);
    }

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        // Early in the stream, opening bins is cheap (build diversity of residuals)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // If current alternatives are bad (item barely fits anywhere), new bin is attractive
        if item_size > 60 {
            score -= 15.0;
        }
        // If many open bins with large mean residual, prefer using them over new bin
        score += 0.4 * mean_residual;
        // Lookahead: empty bin can host both this and next item if they fit
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is close to mean (keep residuals balanced) slightly
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Prefer fuller bins (small residual) generally
    score += 0.2 * bin_residual as f64 * 0.1;

    // Late in stream, avoid opening new bins at all costs
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = pr;

    // Core: reward tight fits (small post-residual), quadratic shaping
    let tight = 1.0 - (pr / cap);
    score -= 4.0 * tight * tight;

    // Lookahead: does the residual after placement still host the next item?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = pr - ni;
            score -= 30.0 + 42.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 27.0; }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 13.0 * (after_next / cap);
            } else if after_next >= ni {
                score -= 9.0 + 4.0 * (after_next / cap);
            }
        } else {
            score += 9.0 * (pr / cap);
            // Near-miss penalty: residual just below next item is dead space
            let miss = 1.0 - pr / ni;
            score += 2.5 * miss * (1.0 - progress);
        }
    }

    // Dead sliver zones
    let dead = pr / cap;
    if dead > 0.0 && dead < 0.11 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 7.5 * (1.0 - dead / 0.11);
    } else if dead > 0.11 && dead < 0.24 && next_item_size > 0 && pr < next_item_size as f64 {
        score += 3.0 * (1.0 - (dead - 0.11) / 0.13);
    }

    if pr == 0.0 { score -= 45.0; }

    // Unique fit gets priority early
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0 * (1.0 - 0.4 * progress);
    }

    // Mean-residual pull: prefer bins with residual near the running mean
    score += (mean_residual - bin_residual as f64) * 0.35;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.4 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.55 {
            score -= base + 14.0 * (1.0 - 2.0 * progress);
        } else {
            score += base + 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 2.5;
        }
        if progress > 0.7 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 6.0;
        }
        if next_item_size > 0 && progress > 0.3 && (bin_capacity as u32) >= item_size + next_item_size {
            let pair_fill = (item_size + next_item_size) as f64 / cap;
            if pair_fill > 0.85 {
                score -= 4.0 * (pair_fill - 0.85) / 0.15 * (1.0 - progress);
            }
        }
    }

    // Multi-fit lookahead: penalize leftovers below half the mean residual
    if next_item_size > 0 && fitting_bins_count > 2 && pr > 0.0 && pr >= next_item_size as f64 {
        let leftover = pr - next_item_size as f64;
        if leftover < mean_residual * 0.5 {
            score += 5.0 * (1.0 - leftover / (mean_residual * 0.5)) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * norm_post);

    // Quadratic penalty on very small post residuals (dead space), stronger late in stream
    let dead = (1.0 - norm_post) * (1.0 - norm_post);
    score += 12.0 * dead * (0.4 + 0.6 * progress);

    // Cubic smooth term: reward tight fits (small post_residual) increasingly
    score -= 20.0 * (1.0 - norm_post).powi(3) * (1.0 - progress);

    // Encourage using bins when few can fit the item (last chance)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when many open bins already exist
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * norm_post);

    // Coupling with mean residual: prefer bins near the mean (balance)
    let dev = (resid - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Lookahead: reward leaving space for the next item, smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64 / cap;
        let usable = if norm_post >= n { 1.0 } else { norm_post / n };
        score -= 10.0 * usable * (1.0 - (norm_post - n).abs());
    }

    // Mild penalty for new empty bin candidate, eased by progress and large items
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress - 5.0 * norm_item;
    }

    score
}

