pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let quarter = (bin_capacity / 4) as i64;
    let fifth = (bin_capacity / 5) as i64;

    // Reward residuals that fall into "usable" harmonic classes (multiples of small units)
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // residual aligns with smallest item class
        } else if pr % quarter == 0 {
            score -= 9.0;
        } else if pr % fifth == 0 {
            score -= 6.0;
        } else if pr % 5 == 0 {
            score -= 2.0;
        } else {
            score += 4.0; // awkward residual class
        }
    }

    // Integer-division threshold coupling: post_residual vs next_item_size
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if pr >= n {
            // next item fits here: strongly reward
            score -= 15.0;
            // extra reward if post_residual / next divides evenly (perfect packing class)
            if n > 0 && pr % n == 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted class
            score += (n - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for the minimum item class
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // New-bin candidate: only prefer when existing residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (post_residual as f64)).abs();
        if open_bins_count > 0 && mean_residual < cap * 0.5 && fragmentation > 0.0 {
            score -= 5.0;
        } else {
            score += 30.0; // generally prefer filling existing bins
        }
    }

    // Mild stream-phase modulation: tighten packing early, allow new bins late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // 2-step lookahead: reward when next item fits, especially exactly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect pair fill
        } else if post_residual > next_item_size {
            let gap = pr - ni;
            score -= 28.0 - gap.min(40.0) * 0.45;
            // after-pair leftover that could fit another typical item is good
            if gap >= next_item_size as f64 {
                score -= 8.0;
            }
        } else {
            let miss = ni - pr;
            score += miss.min(80.0) * 0.35;
        }
    }

    // Dead-space shaping (item sizes 1..100): tiny residual is great, large is waste.
    if pr > 0.0 && pr < 10.0 {
        score -= 8.0;
    } else if pr >= 10.0 && pr < 25.0 {
        score += 3.0;
    } else if pr >= 25.0 {
        score += (pr - 25.0) * 0.30;
    }
    if pr == 0.0 {
        score -= 45.0; // perfect fill
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = (bin_capacity - item_size) as f64;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 20.0;
            }
            // Early stream: opening a fresh bin is cheap insurance.
            if progress < 0.5 {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            // Compare against mean slack of open bins.
            let slack = mean_residual.max(0.0) - item_size as f64;
            if slack < 12.0 {
                score = slack + pr * 0.5 - 10.0;
            } else {
                score = pr + 55.0;
            }
            // Late stream: strongly prefer existing bins.
            if progress > 0.7 {
                score += 10.0 * progress;
            }
        }
    }

    // Tightness bonus (quadratic), borrowed and tuned.
    let tight = 1.0 - pr / cap;
    score -= 4.0 * tight * tight;

    // Balance nudge toward mean residual.
    score += (pr - mean_residual).abs() * 0.05;

    // Stream-progression pressure.
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are small and cannot fit
    // typical future items are unusable dead space -> strong penalty.
    if post_residual > 0 {
        let dead_threshold = 10.0f64; // minimum item size is the usability floor
        if (post_residual as f64) < dead_threshold {
            score += 50.0 * (dead_threshold - post_residual as f64);
        }
        // Non-linear: convex penalty on tight-but-usable leftovers that
        // likely cannot fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward good tight fits relative to bin capacity (best-fit flavor).
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.1 * pressure;

    // New empty bin candidate: penalize mildly so it's only chosen when
    // existing bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * open_bins_count as f64;
        // But if no open bin fits well, allow opening: reduce penalty when
        // the item is large relative to capacity.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Slight tie-break toward bins below mean residual (more packed bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item leaves little waste.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after two placements measures quality.
            let two_step_waste = post_residual - next_item_size;
            score -= 40.0 * (1.0 - two_step_waste as f64 / bin_capacity as f64);
        } else {
            // Next item does NOT fit this bin after placement: penalize leaving
            // a dead space just below next_item_size (unusable gap).
            let gap = next_item_size - post_residual;
            if gap <= 15 {
                score += 25.0 * (1.0 - gap as f64 / 15.0);
            }
        }
    } else {
        // Last item: pure tightness matters most.
        score -= 60.0 * tightness;
    }

    // Prefer bins whose residual is below the mean (compact the "full-ish" bins
    // first), leaving larger residuals in other bins for future items.
    score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive for very large items or
    // when all existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 60 || (next_item_size > 0 && item_size as f64 + next_item_size as f64 > bin_capacity as f64) {
            score -= 70.0;
        }
    }

    // Slight late-stream conservatism: consolidate more as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space strongly (best-fit core).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.08;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if next item would waste this bin's remainder, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item can't use remainder; penalize proportionally to wasted space
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: many open bins with high mean residual
    // -> prefer consolidating into existing bins (avoid bin proliferation).
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    } else if open_bins_count > 2 {
        // open bins are nearly full; opening new bins is fine
        score += 3.0;
    }

    // Time horizon: early in stream, be more exploratory (favor tight fits less,
    // keep bins flexible); late in stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let squeeze = 1.0 + 1.5 * progress;
    score = score / squeeze;

    // Small bonus for leaving residuals that match common item sizes (divisibility heuristic).
    let rem = post_residual % 10;
    if rem == 0 && post_residual > 0 {
        score -= 4.0;
    } else if rem != 0 {
        score += 2.0 * rem as f64 / 10.0;
    }

    // Mild penalty for opening a brand-new bin when decent alternatives exist.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        let urgency = if fitting_bins_count <= 1 { 60.0 } else { 15.0 };
        score += urgency;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: penalize residual, weighted by stream progress (late stream -> tighter packing)
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear polynomial coupling of post_residual with progress
    score += cap * (pr_norm * pr_norm) * (0.5 + 2.0 * progress * (1.0 - progress));

    // Penalize near-empty waste that will likely be dead space
    if pr < item_size as f64 * 0.35 {
        score += cap * (1.0 - pr_norm) * (0.3 + progress);
    }

    // Last-chance bonus: strongly prefer the single fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (pr / (pr + nxt)).sqrt();
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for bins tighter than mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Discourage opening new bins early, allow it late when residual is large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers
    let pr = post_residual;
    let residue = (pr % 10) as f64;
    let tier = (pr / 10) as f64;

    // Penalize awkward residues (dead space not usable by typical items)
    score += 2.0 * residue;

    // Reward large leftover tiers (bin stays reusable)
    score -= 3.0 * tier;

    // Modulo-4 harmonic class on post_residual: multiples of 20 are "harmonic"
    if pr % 20 == 0 && pr > 0 {
        score -= 6.0;
    } else if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let frac = next_item_size as f64 / pr as f64;
            score -= 10.0 * frac;
            // harmonic class of (post_residual mod next_item_size)
            let m = (pr % next_item_size) as f64;
            score -= 2.0 * (1.0 - m / (next_item_size as f64));
        } else {
            score += 4.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when existing bins are quite full / poor fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = (mean_residual / cap) < 0.25;
        if tight || (fitting_bins_count <= 1 && item_size > 50) {
            score -= 20.0 + 10.0 * progress;
        } else {
            score += 25.0; // discourage wasting a fresh bin
        }
    }

    // Mild penalty proportional to crowding of open bins
    score += 0.05 * open_bins_count as f64;

    // Small fraction-of-capacity coupling on item_size class
    let item_class = item_size / 10;
    score -= 0.5 * (item_class as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr * (1.0 + 0.3 * progress);
    let ni = next_item_size as f64;

    // Perfect / near-perfect fill rewards
    if pr == 0.0 {
        score -= 45.0;
    } else if pr <= (item_size as f64) / 8.0 {
        score -= 9.0;
    }

    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        if pr >= ni {
            let slack = pr - ni;
            score -= 30.0 + 42.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 27.0;
            }
            let after_next = pr - ni;
            if after_next > 0.0 && after_next < item_size.max(next_item_size) as f64 {
                score += 13.0 * (after_next / cap);
            } else if after_next >= next_item_size.max(1) as f64 {
                score -= 9.0 + 4.0 * (after_next / cap);
            }
        } else {
            score += 9.0 * (pr / cap);
            let miss = ni - pr;
            if miss < 22.0 {
                score += 0.45 * miss;
            }
            score += 2.5 * (1.0 - pr / ni) * (1.0 - progress);
        }
    }

    // Dead sliver bands
    let dead = pr / cap;
    if dead > 0.0 && dead < 0.11 && next_item_size > 0 && pr < ni {
        score += 8.5 * (1.0 - dead / 0.11);
    } else if dead >= 0.11 && dead < 0.24 && next_item_size > 0 && pr < ni {
        score += 3.0 * (1.0 - (dead - 0.11) / 0.13);
    }

    // Unique-fit preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 24.0;
    }

    // Mean-residual alignment (borrowed from best)
    score += (mean_residual - bin_residual as f64) * 0.35;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let waste_if_placed = post_residual;
        let loose_fit = waste_if_placed as f64 > 1.35 * mean_residual.max(1.0);
        let base = 10.0 * (1.0 - progress) + 15.0 * progress;
        if loose_fit && progress < 0.55 {
            score -= base + 14.0 * (1.0 - 2.0 * progress);
        } else {
            score += base;
            score += 0.55 * open_bins_count.min(30) as f64 * progress;
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && bin_residual >= next_item_size {
            score -= 3.0;
        }
        if progress > 0.65 && next_item_size > 0 && (bin_capacity as u32) >= item_size + next_item_size {
            score -= 4.0;
        }
        if next_item_size > 0 && item_size + next_item_size == bin_capacity && progress < 0.4 {
            score -= 8.0;
        }
        if next_item_size > 0 && progress > 0.3 && (bin_capacity as u32) >= item_size + next_item_size {
            let pair_fill = (item_size + next_item_size) as f64 / cap;
            if pair_fill > 0.85 {
                score -= 4.0 * (pair_fill - 0.85) / 0.15 * (1.0 - progress);
            }
        }
        if next_item_size > 0 && pr < ni && pr < 0.10 * cap {
            score += 6.0;
        }
    }

    // Tightness bonus
    let tight = 1.0 - (pr / cap);
    score -= 4.0 * tight * tight;

    // Post-lookahead leftover quality (borrowed from best)
    if next_item_size > 0 && fitting_bins_count > 2 && pr > 0.0 && pr >= ni {
        let leftover = pr - ni;
        if leftover < mean_residual * 0.5 {
            score += 5.0 * (1.0 - leftover / (mean_residual * 0.5)) * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals in "unusable" gap zones.
    // Gaps of 1..9 are nearly useless (items >= 10 typically, but small items exist);
    // gaps just below common item sizes (11..19) are the worst dead zones.
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 14.0; // tiny unusable sliver
    } else if r >= 10 && r < 20 {
        score += 22.0; // classic dead zone: too small for most items
    } else if r >= 20 && r < 30 {
        score += 6.0; // mild penalty
    }

    // Perfect / near-perfect fits get strong rewards.
    if r == 0 {
        score -= 30.0;
    } else if r <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open pressure and remaining stream length.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 12.0 + open_pressure + 10.0 * (1.0 - progress);
    } else {
        // Slight reward for filling fuller bins (relative fullness).
        score -= (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 3.0;
    }

    // Lookahead: if next item fits the post-residual, this is a great placement.
    if next_item_size > 0 && r >= next_item_size {
        score -= 8.0;
    }
    // If post-residual can't fit the next item but the current bin could have
    // (i.e., we're stranding space relative to lookahead), mild penalty.
    if next_item_size > 0 && r > 0 && r < next_item_size {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (fill the emptier-capacity bins first keeps tight bins tight).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

