pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills the post residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Exact match for next item is a jackpot
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that next item cannot use
        if post_residual < next_item_size {
            score += (post_residual as f64) * 0.3;
        }
    }

    // Prefer bins whose residual deviates from the mean (specialized fits)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev.min(50.0) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect closure of a bin is ideal
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits tightly
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64;
        score += 30.0 - 0.3 * open_bins_count as f64
            + (tightness / 10.0).min(8.0);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can serve next item too
        }
    }

    // Late in the stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Penalize dead space relative to capacity: residuals too small for
    // typical future items are wasted.
    let dead = if post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * 8.0;

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 - 5.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item won't fit here: mild penalty proportional to mismatch.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is penalized mildly,
    // but becomes attractive when mean residual across open bins is low
    // (fragmented state) or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0
            + 0.3 * mean_residual
            + 2.0 * open_bins_count as f64 * (1.0 - progress)
            - 15.0 * progress;
        // Don't open a new bin when a good fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual == 0 && false {
            score += 0.0;
        }
        // Prefer new bin if next item is large and current bins are tight.
        if next_item_size > 60 && mean_residual < 30.0 {
            score -= 10.0;
        }
    }

    // Global balance: prefer bins whose residual deviates from the mean
    // in a way that consolidates space (fill below-average bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Slight time-decay of consolidation pressure late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Smooth non-linear coupling: quadratic in progress, cubic in post_residual ratio.
    let post_ratio = post_residual as f64 / bin_capacity as f64;
    let poly = post_ratio * post_ratio * (3.0 - 2.0 * post_ratio); // smoothstep-like
    score += poly * (1.0 + 2.0 * progress) * 10.0;

    // Favor tight fits more strongly as stream progresses.
    score -= (1.0 - poly) * (1.0 + progress) * (item_size as f64 / bin_capacity as f64) * 8.0;

    // Penalize bins whose residual deviates from mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev * 6.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 {
            score -= 4.0 * (1.0 - (gap as f64 / bin_capacity as f64)) * (1.0 + progress);
        } else {
            score += 3.0 + progress * 3.0;
        }
    }

    // Mild pressure to reuse bins rather than open new ones, growing with open bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 * (0.5 + progress);
    }

    score
}
